-- quest_extra.lua
local ADDON_NAME = ...
OneWoW.CatalogData:Defer(ADDON_NAME, 'quest', function()
return {
[1578] = {id=1578,name="Supplying the Front",level=5,requiredLevel=5,faction="alliance",expansion=7,zoneID=38,mapID=48,description="The mountaineers of Loch Modan are fighting troggs, and having a busy time of it! They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs. That's why my colleague Thorvald is there, trying to keep the mountaineers in good gear. So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged. He might even share his knowledge with you. Thorvald is in Loch Modan's southern guard tower.",starts={{npcID=6031,x=0.49,y=0.424,mapID=87}},ends={{npcID=6030,x=0.236,y=0.744,mapID=48}},coords={x=0.49,y=0.424,source="quest_giver",mapID=48},questType="standard"},
[1582] = {id=1582,name="Moonglow Vest",level=0,requiredLevel=0,faction="alliance",expansion=7,zoneID=1657,mapID=89,description="We in Darnassus, especially we craftsman, are quite busy. Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies. If you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.",starts={{npcID=6034,x=0.604,y=0.37,mapID=89}},ends={{npcID=6034,x=0.604,y=0.37,mapID=89}},coords={x=0.604,y=0.37,source="quest_giver",mapID=89},questType="standard"},
[9897] = {id=9897,name="I'm Saved!",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=3518,mapID=107,description="I don't mind sharing. I'm just glad to be saved from that creep, Gankly! And I collected tons of skins from Zangarmarsh, so it's no problem at all!",starts={{npcID=18294,x=0.714,y=0.406,mapID=107}},ends={{npcID=18218,x=0.714,y=0.406,mapID=107}},coords={x=0.714,y=0.406,source="quest_giver",mapID=107},questType="standard"},
[9999] = {id=9999,name="Buying Time",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=3518,mapID=107,description="As long as the transporters stand, nothing we do to the forge camps will have any permanence. We must find a way to destroy the Legion structures. I need time to devise a plan of attack. If you can keep their engineers and tinkerers busy, it would greatly slow down their progress, buying me the time I need.",starts={{npcID=18417,x=0.274,y=0.43,mapID=107}},ends={{npcID=18417,x=0.274,y=0.43,mapID=107}},coords={x=0.274,y=0.43,source="quest_giver",mapID=107},questType="standard"},
[10004] = {id=10004,name="Patience and Understanding",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=3703,mapID=111,description="Take the blueprints and travel to Shattrath City in the Terokkar Forest. Once at Shattrath, go to the Lower City and look for a mo'arg by the name Sal'salabim . He'll probably be at the bar, drinking away his sorrows. By the way, you may need to convince him to lend his assistance. Try to approach him with patience and understanding. If that does not work, use your fists.",starts={{npcID=18417,x=0.274,y=0.43,mapID=107}},ends={{npcID=18584,x=0.772,y=0.348,mapID=111}},coords={x=0.274,y=0.43,source="quest_giver",mapID=111},questType="standard"},
[11650] = {id=11650,name="Just a Few More Things...",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=4273,description="As you may have noticed, we created the airstrip on the southern border of a magnataur den! The old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb! That's where you come in. I want you to get me everything on this shopping list. Please.",starts={{npcID=25477,x=0.582,y=0.184,mapID=114}},ends={{npcID=25477,x=0.582,y=0.184,mapID=114}},coords={x=0.582,y=0.184,source="quest_giver",zoneID=3537},questType="standard"},
[11797] = {id=11797,name="The Siege",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=3537,mapID=114,description="Well, well, well. It's good to see Arlos bring out the big guns. Don't get me wrong - our lads are doing the best they can, but someone of your renown fighting alongside them could really turn the tides for us. I'm not sure how much longer we can hold out against these undead Nerubians. What do you say you get out there and kill me some creepers? Show these boys how it's done.",starts={{npcID=25816,x=0.564,y=0.696,mapID=114}},ends={{npcID=25816,x=0.564,y=0.696,mapID=114}},coords={x=0.564,y=0.696,source="quest_giver",mapID=114},questType="standard"},
[12047] = {id=12047,name="Something That Doesn't Melt",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=65,mapID=115,description="No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel. I know! I'm brilliant. Bone splinters. There are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.",starts={{npcID=26661,x=0.546,y=0.232,mapID=115}},ends={{npcID=26661,x=0.546,y=0.232,mapID=115}},coords={x=0.546,y=0.232,source="quest_giver",mapID=115},questType="standard"},
[12076] = {id=12076,name="Messy Business",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=65,mapID=115,description="Even at first glance, the sample you brought me shows obvious signs of some kind of corrosive spit. It would be a natural assumption that the same substance these worms use to burrow through the ground has allowed them a formidable weapon against the Ice Giants. Take this scraper and pick a fight with some of the worms. When they spit on you, use the scraper to remove it and bring it back to me. Get me a couple samples - I'm going to have to use it as the base for an elixir.",starts={{npcID=26659,x=0.594,y=0.18,mapID=115}},ends={{npcID=26659,x=0.594,y=0.18,mapID=115}},coords={x=0.594,y=0.18,source="quest_giver",mapID=115},questType="standard"},
[12151] = {id=12151,name="Wanton Warlord",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=65,mapID=115,description="There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this. Follow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge. When Grom'thar the Thunderbringer arrives, kill him and bring me his head.",starts={{npcID=26983,x=0.6,y=0.552,mapID=115}},ends={{npcID=26983,x=0.6,y=0.552,mapID=115}},coords={x=0.6,y=0.552,source="quest_giver",mapID=115},questType="standard"},
[12469] = {id=12469,name="Return to Sender",level=15,requiredLevel=15,faction="both",expansion=7,zoneID=65,mapID=115,description="Upon closer examination, the goblin appears to have been running a pack full of explosives across the wastes for delivery. The harpy feathers half-buried in the snow nearby suggest how he met his ill fate. It appears that the goblin was bringing the explosives towards the Wrath Gate from somewhere to the east. It seems most prudent to follow the ridge back to the east and inform the sender of their runner's fate.",starts={{npcID=26896,x=0.484,y=0.24,mapID=115}},ends={{npcID=26660,x=0.55,y=0.234,mapID=115}},coords={x=0.484,y=0.24,source="quest_giver",mapID=115},questType="standard"},
[12507] = {id=12507,name="Strange Mojo",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=66,mapID=121,description="This bottle of strange mojo may be the key to what is truly going on here. The Zandalari troll Hexxer Ubungo , back at The Argent Stand, may want to take a look at it.",ends={{npcID=28062,x=0.406,y=0.656,mapID=121}},questType="standard"},
[12524] = {id=12524,name="Venture Co. Misadventure",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=3711,mapID=119,description="Ever since we arrived, the Venture Company has hampered our efforts to secure our campsite and survey the area. Normally, we wouldn't care what they were up to, but they've started antagonizing our scouts and shooting down supply flights. We can't allow this insult to stand. Hemet Nesingwary's expedition came here to hunt, and hunt it shall. Go to Swindlegrin's Dig, on the far side of the crystal pillar to the northeast, and kill any Venture Company employee you see!",starts={{npcID=28032,x=0.272,y=0.598,mapID=119}},ends={{npcID=28032,x=0.272,y=0.598,mapID=119}},coords={x=0.272,y=0.598,source="quest_giver",mapID=119},questType="standard"},
[12712] = {id=12712,name="The Key of Warlord Zol'Maz",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=66,mapID=121,description=", we need a key to unlock the chains of the rhino god, Akali. Even now he is being prepared for the slaughter. The Drakkari warlord, Zol'Maz, carries the key. Hearing of your exploits, he has secluded himself and his family at their stronghold up the steps to the northeast. The warlord is strong and you will need help. If you were to combine the tiki, sword and incantation of his family members, you would be able to summon such help as you challenge him before his home's gate.",starts={{npcID=28401,x=0.636,y=0.702,mapID=121}},ends={{npcID=28401,x=0.636,y=0.702,mapID=121}},coords={x=0.636,y=0.702,source="quest_giver",mapID=121},questType="standard"},
[12713] = {id=12713,name="Betrayal",level=20,requiredLevel=20,faction="both",expansion=7,zoneID=66,mapID=121,description="The time has come to end this charade, . As valuable as your information has been, we must bring Drakuru down and bring his project to an end before his freaks are unleashed. We've modified your scepter for the job. When the time is right, you will be able to use it on Drakuru's Blightbloods and turn them against him. It's your only hope of defeating him. Fight well.",starts={{npcID=28518,x=0.14,y=0.738,mapID=121}},ends={{npcID=28518,x=0.14,y=0.738,mapID=121}},coords={x=0.14,y=0.738,source="quest_giver",mapID=121},questType="standard"},
[12819] = {id=12819,name="Just Around the Corner",level=25,requiredLevel=25,faction="both",expansion=7,zoneID=67,mapID=120,description="Blast it! Where are my tools? I had them here just a moment ago. Oh! I probably forgot them when I was setting up that minefield in the west. That's mildly inconvenient. I'd be quite appreciative if you could go get them for me. You'll need to watch your step though... you should be able to use the same path that I did to get out. Oh, and don't try to fly in... I had the presence of mind to set up turrets to shoot down anything that might fly, and they aren't very discerning in who they target.",starts={{npcID=29431,x=0.41,y=0.864,mapID=120}},ends={{npcID=29431,x=0.41,y=0.864,mapID=120}},coords={x=0.41,y=0.864,source="quest_giver",mapID=120},questType="standard"},
[12890] = {id=12890,name="If Size Mattered...",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=67,mapID=120,questType="standard"},
[12980] = {id=12980,name="The Armor's Secrets",level=25,requiredLevel=25,faction="both",expansion=7,zoneID=67,mapID=120,description="The presence of that armor plate is disorienting, but we need to find out all we can from it. It could be part of one of Valduran's schemes. He's dedicated an extraordinary amount of effort to mining, refining, smithing, and testing this metal. To the east, along the northern mountain face, is a building called Mimir's Workshop. It hasn't been used in quite some time, but if we're lucky, some of its attendants are still functional. Take your armor plate there and learn what you can from it.",starts={{npcID=30152,x=0.312,y=0.38,mapID=120}},ends={{npcID=30152,x=0.312,y=0.38,mapID=120}},coords={x=0.312,y=0.38,source="quest_giver",mapID=120},questType="standard"},
[13011] = {id=13011,name="Culling Jorcuttar",level=25,requiredLevel=25,faction="both",expansion=7,zoneID=67,mapID=120,description="The jormungar are a nuisance best dealt with quickly. If given any quarter, they breed like hares and spread like fire. They have appeared southwest of here, in the Hibernal Cavern. If their spawnmother is not slain soon, they will gain a foothold in our region. She cannot refuse food. Take this knife and get the flank of a bear corpse from their cave. Place it near her crater and kill her as she feeds.",starts={{npcID=30105,x=0.654,y=0.602,mapID=120}},ends={{npcID=30105,x=0.654,y=0.602,mapID=120}},coords={x=0.654,y=0.602,source="quest_giver",mapID=120},questType="standard"},
[13058] = {id=13058,name="Changing the Wind's Course",level=25,requiredLevel=25,faction="horde",expansion=7,zoneID=67,mapID=120,description="At last, we have all that we need to right the wrongs of the North Wind and its followers. You have attuned the Lorehammer to Stormhoof's time and his persona. Take the hammer again, head to the Temple of Life in the plains to the northwest. Use the hammer to assume the role of Stormhoof. Face the North Wind as Stormhoof, but realize that for the timeline to be restored, Stormhoof must die as the North Wind weakens. Then, you must find and use the Horn of Elemental Fury to destroy the North Wind.",starts={{npcID=30381,x=0.656,y=0.514,mapID=120}},ends={{npcID=30381,x=0.656,y=0.514,mapID=120}},coords={x=0.656,y=0.514,source="quest_giver",mapID=120},questType="standard"},
[13270] = {id=13270,name="Cloth Scavenging",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=3537,mapID=114,starts={{npcID=26969,x=0.416,y=0.534,mapID=114}},ends={{npcID=26969,x=0.416,y=0.534,mapID=114}},coords={x=0.416,y=0.534,source="quest_giver",mapID=114},questType="standard"},
[13272] = {id=13272,name="Cloth Scavenging",level=10,requiredLevel=10,faction="both",expansion=7,zoneID=4395,mapID=125,questType="standard"},
[13528] = {id=13528,name="Buzzbox 723",level=5,requiredLevel=5,faction="alliance",expansion=7,zoneID=148,mapID=62,description="There are a couple other forms of wildlife that we've verified infected. It's actually good news that the crabs appear to have caught this from the bears - hopefully that means this all stems from one source. We need to focus our attention on those bears now. Buzzbox 723 is near the waterfalls to the east. It's going to be messy work, but it's necessary - I'll need you to bring some fresh bear guts to that buzzbox for analysis. We'll go from there once I have the information.",starts={{npcID=32977,x=0.512,y=0.196,mapID=62}},ends={{npcID=194122,x=0.542,y=0.293,mapID=62}},coords={x=0.512,y=0.196,source="quest_giver",mapID=62},questType="standard"},
[13566] = {id=13566,name="Ritual Materials",level=5,requiredLevel=5,faction="alliance",expansion=7,zoneID=148,mapID=62,description="While we tend to Grimclaw, I would like you to peacefully gather some ritual materials for me from the nearby wildlife. I need whiskers from the moonstalkers to the west- pluck them from the sleeping ones and move away quickly. I need hair from the doe to the east, just avoid the stags. Finally, I need fur from the bears along the water to the northeast. Wait until they catch a fish, then get the sample quickly and get away before they finish eating. Please do not harm any of them.",starts={{npcID=33048,x=0.43,y=0.39,mapID=62}},ends={{npcID=33048,x=0.43,y=0.39,mapID=62}},coords={x=0.43,y=0.39,source="quest_giver",mapID=62},questType="standard"},
[13871] = {id=13871,name="Security!",level=7,requiredLevel=7,faction="horde",expansion=7,zoneID=331,mapID=63,description="It's not as like I haven't got enough to think about here! Keeping this place operational is hard enough without constant elf and draenei harassment. Now, on top of everything, there's an assassin lurking around the camp who's killed an important diplomat... on my watch! Whoever it is couldn't have gotten far, . Scour the camp until you find her and then avenge the diplomat! At least I can bring the assassin's head with me when I have to answer to Hellscream.",starts={{npcID=17304,x=0.908,y=0.582,mapID=63}},ends={{npcID=17304,x=0.908,y=0.582,mapID=63}},coords={x=0.908,y=0.582,source="quest_giver",mapID=63},questType="standard"},
[25552] = {id=25552,name="Brood of Evil",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=616,mapID=198,description="This egg you recovered is an alarming sign, . The Twilight dragons are usually raised from stolen eggs from other dragonflights, which are then modified through dark magic. This \"natural\" egg is evidence that one of their matriarchs has become a viable broodmother. We must destroy her before her brood spreads. Go to the Ascendant's Rise where they claim these aberrations are kept and slay one of the juvenile drakes. We will use its skull to lure out its mother.",starts={{npcID=40816,x=0.722,y=0.738,mapID=198}},ends={{npcID=40816,x=0.722,y=0.738,mapID=198}},coords={x=0.722,y=0.738,source="quest_giver",mapID=198},questType="standard"},
[26415] = {id=26415,name="Questflag for Captain's Log",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=5042,mapID=207,questType="standard"},
[26453] = {id=26453,name="A Helping Hand",level=7,requiredLevel=7,faction="alliance",expansion=7,zoneID=331,mapID=63,description="Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale . The task of building won't be easy, , for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested his way. Speak to me again and I will arrange for fast transport for you to their location.",starts={{npcID=17106,x=0.35,y=0.498,mapID=63}},ends={{npcID=17291,x=0.868,y=0.448,mapID=63}},coords={x=0.35,y=0.498,source="quest_giver",mapID=63},questType="standard"},
[26710] = {id=26710,name="Lost In The Deeps",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,mapID=207,description="Pebble has gotten himself lost again, somewhere deep in the Crumbling Depths. He's fortunate that his size makes him unworthy of the effort for those gyreworms, but it's only a matter of time before he stumbles too close to one and gets eaten. Whatever he's so intent on down there is certainly not worth it. He seems to like you. Please, go and find him and bring him out of those tunnels to safer playing grounds.",starts={{npcID=44945,x=0.554,y=0.14,mapID=207}},ends={{npcID=44945,x=0.554,y=0.14,mapID=207}},coords={x=0.554,y=0.14,source="quest_giver",mapID=207},questType="standard"},
[26755] = {id=26755,name="Keep Them off the Front",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,mapID=207,description="Oh good, you brought another catapult with you! Clay might be older than dirt, but he makes a mean war machine. Well, you didn't bring it all the way out here for your health, flesh bag. Get in one of those things and bombard the fungal terrors and reinforcements streaming out of Needlerock Slag. We have to keep them off the front!",starts={{npcID=43897,x=0.226,y=0.52,mapID=207}},ends={{npcID=43897,x=0.226,y=0.52,mapID=207}},coords={x=0.226,y=0.52,source="quest_giver",mapID=207},questType="standard"},
[26771] = {id=26771,name="Testing the Trap",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,mapID=207,description="You must set the trap for the matriarch now. Go to the western end of the Alabaster Shelf and place the trapped basilisk meat in the center of the feeding grounds.",starts={{npcID=44010,x=0.644,y=0.822,mapID=207}},ends={{npcID=44010,x=0.644,y=0.822,mapID=207}},coords={x=0.644,y=0.822,source="quest_giver",mapID=207},questType="standard"},
[27787] = {id=27787,name="Skullcrusher the Mountain",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=4922,mapID=241,description="It was a trap! Cho'gall lured you in with the Hammer of Twilight so that his gronn could finish you off. Survive and slay Skullcrusher the Mountain !",starts={{npcID=46717,x=0.452,y=0.878,mapID=241}},ends={{npcID=45668,x=0.434,y=0.574,mapID=241}},coords={x=0.452,y=0.878,source="quest_giver",mapID=241},questType="standard"},
[28712] = {id=28712,name="Enter the Dragon Queen",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=4922,mapID=241,description="Hello, . I wish we could meet in more favorable circumstances. The world hangs by a thread, and all that the Titans have wrought may be in jeopardy. It saddens me greatly, but my judgment is final. Deathwing - the horrific creature that was once the Earth Warder and once my friend - must be destroyed. I have prepared a site atop the Highlands, to the west of the Vermillion Redoubt, where I can bring about his end. Seek out the Circle of Life and speak with Lirastrasza within. I will join you there.",starts={{npcID=47603,x=0.218,y=0.57,mapID=241}},ends={{npcID=49417,x=0.148,y=0.162,mapID=241}},coords={x=0.218,y=0.57,source="quest_giver",mapID=241},questType="standard"},
[28732] = {id=28732,name="This Can Only Mean One Thing...",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=25,description="Raz and I were enlisted by the Guardians of Hyjal to investigate the re-emergence of Ragnaros into our world. Let me go ahead and confirm that he is back and he is angry! We also have evidence that these Twilight's Hammer cultists are moving elementals from here to Blackrock Caverns , over in the Eastern Kingdoms. Raz and I were about to head over there to investigate. We've got room for another in the mole machine if you're interested. Just meet us on the inside and we'll begin our journey.",starts={{npcID=49444,x=0.426,y=0.28,mapID=198}},coords={x=0.426,y=0.28,source="quest_giver",zoneID=616},questType="standard"},
[28869] = {id=28869,name="Pebble",level=30,requiredLevel=30,faction="both",expansion=7,zoneID=5042,mapID=207,description="If you hadn't noticed, there's a very small elemental that has taken a liking to you. If you stay on the ground for even a few moments, I'm sure you'll spot him. You seem to be quite adept at making friends down here. A good talent to have.",questType="standard"},
[28876] = {id=28876,name="To the Mor'shan Rampart",level=7,requiredLevel=7,faction="horde",expansion=7,zoneID=17,mapID=10,description="Kadrak at the Mor'shan Rampart to the north is calling for aid. The rampart rests on the border between the Northern Barrens and Ashenvale . It is the front line in the fight against the Alliance. We're driving the night elves out of the forest. We'll claim its resources for the Horde! To get there, take the Gold Road north out of the Crossroads. Destiny calls!",starts={{npcID=3429,x=0.486,y=0.596,mapID=10}},ends={{npcID=8582,x=0.426,y=0.15,mapID=10}},coords={x=0.486,y=0.596,source="quest_giver",mapID=10},questType="standard"},
[29123] = {id=29123,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",starts={{npcID=52669,x=0.272,y=0.624,mapID=198}},ends={{npcID=52669,x=0.272,y=0.624,mapID=198}},coords={x=0.272,y=0.624,source="quest_giver",mapID=198},questType="standard"},
[29127] = {id=29127,name="Rage Against the Flames",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=616,mapID=198,description="Of all of our tasks here in Hyjal, the most pressing is simple: destroy these invaders. The very nature of fire is that it is all-consuming. Lower your defense for just a moment and it will destroy everything in sight. Kill any of the fiery invaders you find. Every enemy defeated purchases more time for Hyjal.",starts={{npcID=52669,x=0.272,y=0.624,mapID=198}},ends={{npcID=52669,x=0.272,y=0.624,mapID=198}},coords={x=0.272,y=0.624,source="quest_giver",mapID=198},questType="standard"},
