[29270] = {id=29270,name="Time Grows Short",level=35,requiredLevel=35,faction="both",expansion=7,zoneID=3537,mapID=114,description="Tarecgosa is bound to you, , but only temporarily. An aspect's power is required to permanently seal her essence. Malygos's successor will not be chosen until Azeroth's moons next eclipse, and the bond you share will not last until then. Fortunately, there is a way to buy us the time we need. Powerful elements exist that can extend the ritual's effects. Some of these can be found in the Plane of Fire, with which you've become familiar. Obtain them, , and sustain Tarecgosa until the eclipse.",starts={{npcID=53210,x=0.31,y=0.24,mapID=114}},ends={{npcID=53215,x=0.23,y=0.308,mapID=114}},coords={x=0.31,y=0.24,source="quest_giver",mapID=114},questType="raid"},
[29281] = {id=29281,name="Additional Armaments",level=32,requiredLevel=32,faction="both",expansion=7,zoneID=616,mapID=198,description="These druids be lackin' the tools ta properly handle the job out 'ere. I got meself a buddy back at day ol' stag shrine through the portal though. If we were ta be gettin' reunited, we'd sure have some real toys ta use against ol' Ragboy and 'is cronies. Take some of dem mark things an' go find Matoclaw . Ask her fer Ricket. We need'r here so we can be causin' some real trouble.",starts={{npcID=53214,x=0.47,y=0.9,mapID=198}},ends={{npcID=52669,x=0.272,y=0.624,mapID=198}},coords={x=0.47,y=0.9,source="quest_giver",mapID=198},questType="standard"},
