[46787] = {id=46787,name="Further Advancement",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=139,mapID=23,description="As the war against our enemies progresses, so must we. We are now able to perform new research. Seek out Sir Alamande Graythorn to continue advancing the Order Hall.",questType="standard"},
