[46796] = {id=46796,name="Paragon of Highmountain",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7731,mapID=650,description="The grateful Highmountain Tribes have requested your presence. They wish to reward you for your exceptional aid.",ends={{npcID=106902,x=0.382,y=0.458,mapID=650}},questType="standard"},
[46801] = {id=46801,name="Ship - Val'sharah",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
