[46812] = {id=46812,name="Draconic Secrets",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8672,description="Arthas never found the prize he sought, Deathlord. It is ours by right. The dragons must know where the resting place of their kin resides. Find a member of the bronze flight, the tenders of history. Do not be merciful.",questType="standard"},
[46813] = {id=46813,name="The Lost Glacier",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8676,description="Do you know why the red dragonflight seeks to prevent us from finding our prize? The bones of a great red dragon teem with the essence of life, even decades after its passing. You will consume this life essence, blight it, and turn it to undeath. And then you will raise a dragon. Fly now into the north. Find this glacier, and your destiny.",questType="standard"},
