[46846] = {id=46846,name="The Word of Zul",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="I have a mundane task for you. Our esteemed Prophet Zul has words to distribute to very specific individuals in de port. And he requested you be de one to deliver dem. Don't ask me why he didn't just have you deliver these when you were here de first time. De prophet is notorious for not sharing all of his visions.",starts={{npcID=126684,x=0.5,y=0.848,mapID=1165}},ends={{npcID=126684,x=0.5,y=0.848,mapID=1165}},coords={x=0.5,y=0.848,source="quest_giver",mapID=1165},questType="standard"},
[46904] = {id=46904,name="Boon of the Command Center",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7543,mapID=646,starts={{npcID=120183,x=0.446,y=0.632,mapID=646}},ends={{npcID=120183,x=0.446,y=0.632,mapID=646}},coords={x=0.446,y=0.632,source="quest_giver",mapID=646},questType="standard"},
[46926] = {id=46926,name="Shakedown",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Where are de guards? Princess Talanji has convinced King Rastakhan to permit outsiders in our port. For de first time in centuries, we have allowed non-trolls to set foot on our shores and peddle their wares. And now trolls of lesser tribes seem to think dey can take advantage of these merchants? I will not allow dis sort of behavior. While I investigate why de merchants are not protected, I want you to work your way through de bazaar and slay any thugs you find. Send dem a message.",starts={{npcID=135441,x=0.5,y=0.85,mapID=1165}},ends={{npcID=135441,x=0.5,y=0.85,mapID=1165}},coords={x=0.5,y=0.85,source="quest_giver",mapID=862},questType="standard"},
[46927] = {id=46927,name="Punishment of Tal'aman",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Look, Zolani is going about dis all wrong. If you want de Amani, or anyone, to pay attention, take out their leaders. Go into Tal'aman and look for their mighty gong. Challenge four of their disciples to combat and slay dem.",starts={{npcID=126684,x=0.5,y=0.848,mapID=1165}},ends={{npcID=126684,x=0.5,y=0.848,mapID=1165}},coords={x=0.5,y=0.848,source="quest_giver",mapID=1165},questType="standard"},
[46928] = {id=46928,name="Punishment of Tal'farrak",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="De Sandfury tribe may have had a hand in some crime around here, but it is really their false belief system dat makes dem do dis sort of thing. Enter Tal'farrak, bang de gong within, and face de hydra dey keep as a sacred pet. Bring me dis thing's tongues.",starts={{npcID=126684,x=0.5,y=0.848,mapID=1165}},ends={{npcID=126684,x=0.5,y=0.848,mapID=1165}},coords={x=0.5,y=0.848,source="quest_giver",mapID=1165},questType="standard"},
[46929] = {id=46929,name="Deterrent",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="General Jakra'zet had orders to ensure dis place had protection. Guard protection. I see none of dat. Jakra'zet is a stubborn general, and one I have had my eye on for a while now. Regardless, we must remind dese lesser tribes who rules dis city with a message dey will understand. I charge you with collecting heads. Enter Tal'farrak and Tal'aman, and collect a quota of heads.",starts={{npcID=135441,x=0.5,y=0.85,mapID=1165}},ends={{npcID=135441,x=0.5,y=0.85,mapID=1165}},coords={x=0.5,y=0.85,source="quest_giver",mapID=862},questType="standard"},
[46930] = {id=46930,name="Rastakhan",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="You stand before General Jakra'zet , lord of de armies of Zandalar, enforcer of her seas and bringer of war. And I do not like you. It took years to earn my place here after your Horde laid waste to my people. You will not undo what I have built. I will see you kneel before King Rastakhan . I will watch you beg as he lets me take your head for a trophy. I will fling your corpse into de wastes of Vol'dun. Her \"Highness\" may object... but she is not queen yet. Come. Let us fly to your fate.",starts={{npcID=122661,x=0.5,y=0.824,mapID=1165}},ends={{npcID=120740,x=0.498,y=0.464,mapID=1165}},coords={x=0.5,y=0.824,source="quest_giver",mapID=1165},questType="standard"},
[46931] = {id=46931,name="Speaker of the Horde",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Your Horde has grown powerful, eclipsing some of de troll empires in its magnitude. For saving my daughter, you have earned de right to a presence in my city. Since my daughter has taken such a fondness to you, you may join her in de Great Seal beneath us. De servants there will answer to you now. Talanji seems excited by whatever she has planned for your people. I look forward to being amused by it later. Zolani can show you a way down dat does not involve falling.",starts={{npcID=120740,x=0.498,y=0.464,mapID=1165}},ends={{npcID=120168,x=0.344,y=0.416,mapID=1165},{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=120168,x=0.682,y=0.47,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165},{npcID=120168,x=0.344,y=0.414,mapID=1165},{npcID=120168,x=0.688,y=0.452,mapID=1165},{npcID=133050,x=0.396,y=0.688,mapID=1165}},coords={x=0.498,y=0.464,source="quest_giver",mapID=862},questType="standard"},
