[46957] = {id=46957,name="Welcome to Zuldazar",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Champion of de Horde, welcome to de city of Zuldazar , capital of de Zandalari Empire, de jewel of all troll civilizations. I would have you ride by my side so we might discuss matters without prying ears close at hand.",starts={{npcID=132332,x=0.58,y=0.624,mapID=862}},ends={{npcID=122661,x=0.5,y=0.824,mapID=1165}},coords={x=0.58,y=0.624,source="quest_giver",mapID=1165},questType="standard"},
