[47002] = {id=47002,name="The Crown of the Triumvirate",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=8701,mapID=882,description="We begin our search now, . The Crown of the Triumvirate was created to spread the Light's touch to all. With it, our culture thrived. When I fled Argus with the Draenei, I took one shard of the Crown with me to ensure that it would not fall into the wrong hands. Kil'jaeden and Archimonde's fragments are still here. I will seek them out, but you will need to safeguard me while I search. Stay close, my friend.",questType="standard"},
