[47029] = {id=47029,name="Holy: A Threat in Val'sharah",level=45,requiredLevel=45,faction="none",expansion=7,description="It appears you have grown strong enough to take on another Legion threat. If you could speak to Archmage Modera in Dalaran as soon as possible, the Council would be in your debt.",questType="standard"},
