[47037] = {id=47037,name="Balance: The Twisted Twin",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=7543,mapID=646,description="I have a request from an old friend, Karam Magespear , to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him. Originally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order. Find Karam in the Legerdemain Lounge and see if you can lend a hand. Specialization: Balance Druid",ends={{npcID=116175,x=0.564,y=0.272,mapID=646}},questType="standard"},
[47039] = {id=47039,name="Marksmanship: The Twisted Twin",level=45,requiredLevel=45,faction="alliance",expansion=7,zoneID=7543,mapID=646,description="I have a request from an old friend, Karam Magespear , to help find his brother, Raest. Karam fears that Raest is dealing with dark powers, and wishes to stop him. Originally Raest trained with the Kirin Tor, but such were his aspirations of power that he turned to the forbidden art of Necromancy. He was discovered and expelled from our order. Find Karam in the Legerdemain Lounge and see if you can lend a hand. Specialization: Marksmanship Hunter",ends={{npcID=116175,x=0.564,y=0.272,mapID=646}},questType="standard"},
