[47043] = {id=47043,name="Havoc: The Thieving Apprentice",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=16,mapID=76,description="The Focusing Iris has been stolen from the Dalaran Vaults! The thief was a mage of some skill, but we've been unable to track him. Fortunately, the thief dropped a note from his master, addressing him as one of his \"apprentici.\" I know of only one mage who uses that particular pluralization - Archmage Xylem. I'll need you to investigate. In Azshara you will find his tower where he trains his apprentices. Go there, and see what Xylem is up to. Specialization: Havoc Demon Hunter",ends={{npcID=115791,x=0.25,y=0.386,mapID=76}},questType="standard"},
