[47103] = {id=47103,name="Journey to Nazmir",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="It is time to put an end to de blood trolls in Nazmir before their monstrous horde descends upon Zuldazar. My most loyal followers are willing to come with me to dat cursed place. But it will not be enough. I am relieved dat you and de Horde are willing to help. Rokhan and his darkspears are getting ready to leave. I will finish my preparations here. Meet with Rokhan and make your way to Nazmir , I will see you there.",starts={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},ends={{npcID=126549,x=0.516,y=0.412,mapID=1165}},coords={x=0.498,y=0.422,source="quest_giver",mapID=1165},questType="standard"},
[47105] = {id=47105,name="Into The Darkness",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We are in Nazmir to stop de blood trolls from destroying Zuldazar. Dis is de start of our campaign to end dem. Dese monsters want my kingdom and its people destroyed. We are going destroy dem first. My father thinks de blood troll threat will go away on its own, like it did in de past. But things are different now. Rokhan and de others are moving north of here to establish a camp for us to stay in, den dey will join us in de fight. Are you ready?",starts={{npcID=120904,x=0.43,y=0.86,mapID=863}},ends={{npcID=130844,x=0.452,y=0.71,mapID=863}},coords={x=0.43,y=0.86,source="quest_giver",mapID=863},questType="standard"},
[47130] = {id=47130,name="Improper Burial",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De blood trolls are gathering de corpses of my people for their blood magic. Dis ends today. I will take care of de corpses here. Take dis torch. Its fires are blessed by priests of Bwonsamdi, de loa of death. Burn any corpses of my people dat you see. Each corpse burned means less power for dese monsters' blood magic.",starts={{npcID=121241,x=0.456,y=0.748,mapID=863},{npcID=130844,x=0.452,y=0.71,mapID=863}},ends={{npcID=121241,x=0.456,y=0.748,mapID=863}},coords={x=0.456,y=0.748,source="quest_giver",mapID=863},questType="standard"},
[47188] = {id=47188,name="The Aid of the Loa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De blood trolls are stronger than ever, thanks to dis G'huun... and now dey are empowering a giant construct! We need a plan to destroy dat construct, G'huun, and de blood trolls. It is not going to be easy. But I have an idea.",starts={{npcID=121288,x=0.392,y=0.79,mapID=863}},ends={{npcID=121288,x=0.392,y=0.79,mapID=863}},coords={x=0.392,y=0.79,source="quest_giver",mapID=863},questType="standard"},
[47193] = {id=47193,name="Battle for Azsuna",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[47194] = {id=47194,name="Battle for Highmountain",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[47195] = {id=47195,name="Battle for Stormheim",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[47196] = {id=47196,name="Battle for Val'sharah",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=7334,mapID=630,questType="standard"},
[47241] = {id=47241,name="The Shadow of Death",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We have four loa, but we only know where one is: Bwonsamdi. As uncomfortable as it makes me, I am prepared to do anything to stop de blood trolls... even if it means dealing with de loa of death. Ages ago, Bwonsamdi had a temple here in Nazmir . My scrying has revealed a few locations to de north where I sense a magical presence. Search dem for clues. Hurry, . Zuldazar will fall if we cannot obtain Bwonsamdi's help!",starts={{npcID=121288,x=0.392,y=0.79,mapID=863}},ends={{npcID=122102,x=0.366,y=0.538,mapID=863}},coords={x=0.392,y=0.79,source="quest_giver",mapID=863},questType="standard"},
[47244] = {id=47244,name="A Culling of Souls",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Only two types enter Bwonsamdi's temple anymore: those looking to make a deal with death, and de dead. You do not stink, so I guess you are de former. I am headed to de temple myself, so how about a trade? See de land across de bridge? Dere is a witch named Najima dat I have been tracking. De blood trolls are corrupt to de core, but their souls are useful as offerings to Bwonsamdi. She is too strong for me to deal with, but if you can slay her, I will take you to de temple. I give you my word.",starts={{npcID=122102,x=0.366,y=0.538,mapID=863}},ends={{npcID=124428,x=0.396,y=0.438,mapID=863}},coords={x=0.366,y=0.538,source="quest_giver",mapID=863},questType="standard"},
[47245] = {id=47245,name="Getting the Message",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Da loa be powerful, but we be needin' soldiers if we gonna have a chance of stopping dem blood trolls from building dat giant of theirs. If we not be able ta destroy dat thing before it be finished, den Zuldazar and all of our people gonna be dead! We need da help of da Horde! Word of da situation already be sent to da warchief. As soon as we be hearin' her reply, we can mov-- Wait... what be dat noise?",starts={{npcID=121289,x=0.392,y=0.79,mapID=863},{npcID=131213,x=0.674,y=0.422,mapID=863}},ends={{npcID=131213,x=0.674,y=0.422,mapID=863}},coords={x=0.392,y=0.79,source="quest_giver",mapID=863},questType="standard"},
[47246] = {id=47246,name="Remnants of the Damned",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Ever since da spirits have begun calling upon this \"G'huun\" me temple has been covered with the unbearable taint of the undead. Da undead be an abomination, but da bloodstones that create them be powerful. They could be of use ta Bwonsamdi. If you wish ta show me your fervor, then cleanse me temple of their filth and bring me their bloodstones.",questType="standard"},
[47247] = {id=47247,name="That Which Haunts the Dead",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Bwonsamdi knows why ya be here. Ya be seekin' me favor. Bwonsamdi ponders you silently.> A test, ta see if ya be worth Bwonsamdi 's time. Dere be spirits whose prayers sing of something called \"G'huun.\" Dey pay me homage no more. I will not allow da desecration of me own temple! Go and subdue da strongest of da ancient spirits. If ya do dis for me, ya may be worth da trouble after all.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=122688,x=0.396,y=0.246,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[47249] = {id=47249,name="Soulbound",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Ya did well with me tasks. I be thinkin' ya show promise. Ya might be worthy of a deal. Very well, I pledge ta lend ya me powers ta use against ya foes. In exchange, ya be sendin' one million souls ta Bwonsamdi ! No need ta look shocked, ya be plenty capable of doing dis. Come, meet with me at da Court of Spirits. Dere, we will finalize our agreement.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=122766,x=0.394,y=0.302,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[47250] = {id=47250,name="We'll Meet Again",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Now, it be time for ya ta leave. Dere be many of dem blood troll souls for ya ta be sendin' to da Other Side for Bwonsamdi , and ya not gonna find any more of dem here.",starts={{npcID=122766,x=0.394,y=0.302,mapID=863}},ends={{npcID=127004,x=0.394,y=0.438,mapID=863}},coords={x=0.394,y=0.302,source="quest_giver",mapID=863},questType="standard"},
[47262] = {id=47262,name="Ending the Blood Trolls",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De loa are smiling on us today. De \"matriarch\" of dese blood trolls, a sick monster named Ateena, is up ahead. We have a change in plans, . We will end dis threat now. We kill Ateena and de blood trolls will be thrown into chaos. She is a powerful hexxer. Go start de fight and I will ambush and catch her off guard. Let us get moving. We will be back in Zuldazar before de day is over.",starts={{npcID=121241,x=0.456,y=0.748,mapID=863}},ends={{npcID=130844,x=0.452,y=0.71,mapID=863}},coords={x=0.456,y=0.748,source="quest_giver",mapID=863},questType="standard"},
[47263] = {id=47263,name="A Time of Revelation",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I can feel Ateena's dark voodoo up ahead. We need to stop whatever she is planning with dis \"G'huun\". Be ready for anything, . We do not know what power Ateena truly has. I do know one thing. If G'huun is threatening my people, den it will die, just like Ateena.",starts={{npcID=130844,x=0.452,y=0.71,mapID=863}},ends={{npcID=121288,x=0.392,y=0.79,mapID=863}},coords={x=0.452,y=0.71,source="quest_giver",mapID=863},questType="standard"},
[47264] = {id=47264,name="Leave None Standing",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Now you see what my father refuses to acknowledge. De blood trolls are slaughtering us, and dey need to be stopped. Our plan is simple, . We will go out dere and kill as many of dese blood trolls as we can. You go east, I go north. Meet with me after and we will see what is left to do. We will teach dese blood trolls to fear de Zandalari!",starts={{npcID=130844,x=0.452,y=0.71,mapID=863}},ends={{npcID=121241,x=0.456,y=0.748,mapID=863}},coords={x=0.452,y=0.71,source="quest_giver",mapID=863},questType="standard"},
[47283] = {id=47283,name="Chop, Chop!",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9439,mapID=14,description="Throm-ka, . I'm always looking for someone who thinks they can swing an axe with the best of them. If you can remove that sapling without much trouble, I'm sure we can find a better use for your skills.",starts={{npcID=129107,x=0.46,y=0.196,mapID=14}},ends={{npcID=129107,x=0.46,y=0.196,mapID=14}},coords={x=0.46,y=0.196,source="quest_giver",mapID=14},questType="standard"},
[47288] = {id=47288,name="Valuable Fossils",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[47290] = {id=47290,name="World Event Dungeon - Hummel",level=1,requiredLevel=1,faction="none",expansion=7,questType="standard"},
[47332] = {id=47332,name="Your Next Move",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,questType="standard"},
[47422] = {id=47422,name="Dire Situation",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Good news, we found de source of de corruption. De bad news, it is a ritual on de apex of Zanchul. Blood magic wielding heretics are empowering some sort of dire troll up dere. How it made it all de way to de apex without us catching it is something I am sure Raal and I will be arguing about for de next year. Come, let us stop dis heresy.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165},{npcID=127101,x=0.424,y=0.09,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47423] = {id=47423,name="Forbidden Practices",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="You come at a good time, $p. I have need of a weapon such as yourself. Yazma's spies say dere are blood cultists in our ranks. King Rastakhan has charged me with tracking down any trolls guilty of practicing blood magic and purging dem. Take dis totem, route out those with de stench of blood magic, and cleanse dem from dis holy place. When you are done, tell dat lazy Hexlord Raal to get off his perch and help keep dis place secure.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126564,x=0.408,y=0.114,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47432] = {id=47432,name="The Bargain is Struck",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Now dat you have declared a patron loa for your time here in Zuldazar , you should inform de king of your decision. He will appreciate dat you chose to follow de great Pa'ku.",starts={{npcID=127489,x=0.498,y=0.334,mapID=1165}},ends={{npcID=120740,x=0.498,y=0.464,mapID=1165}},coords={x=0.498,y=0.334,source="quest_giver",mapID=1165},questType="standard"},
[47433] = {id=47433,name="Offensively Defensive",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Let me guess, Loti had you kill any trolls dat smelled of blood magic, yes? Well, dat is barely a half measure. See, blood magic comes from de old ways, and our people have only been giving in to its allure since de walls fell on our northern border. Come, we will go for a little ride and patrol de border to Nazmir. Dat is where all dese bad ideas are coming from.",starts={{npcID=126564,x=0.408,y=0.114,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165}},coords={x=0.408,y=0.114,source="quest_giver",mapID=1165},questType="standard"},
[47434] = {id=47434,name="Restraining Order",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="\"Something feels different\"? Dat was all Raal said? His flock of pterrordaxes have swarmed de courtyard of Zanchul. Dey are being driven mad. Shoo dem away before dey hurt demselves or others.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126564,x=0.408,y=0.114,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47435] = {id=47435,name="Pterrortorial Dispute",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="De courtyard of Zanchul has been overrun by pterrordaxes driven mad by some dark ritual. Power is coalescing here, and it is hard to tell who or what is causing it. I need to track down de source. In de meantime, you take dis, de power of Gonk, and call his allies to help you in battle. Slay dese maddened pterrordaxes. When you are done, tell Raal to get his flock under control.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126564,x=0.408,y=0.114,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47437] = {id=47437,name="Competitive Devotion",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="Okay, I know dis situation is serious, but she gave you de power of her loa? Sounds to me like Loti is more big on recruiting than on dealing with dis blood troll threat. Inside de temple behind me are three guardians. When I walked in dere, de things tried to kill me. Me! Someone has corrupted our own guardians. Here, I will lend you de voice of my own loa, Pa'ku, de pterrordax. Use it to crush dis corruption.",starts={{npcID=126564,x=0.408,y=0.114,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165}},coords={x=0.408,y=0.114,source="quest_giver",mapID=1165},questType="standard"},
[47438] = {id=47438,name="Picking a Side",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Look, dis has gone on long enough, $p. I am not one to hold a grudge, but I will be damned if I let you double dip with Raal's loa and my own. Time has come to pick a loa. De loa are not de sharing type.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=1165},questType="standard"},
[47439] = {id=47439,name="Gonk, Lord of the Pack",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="You can find Gonk in his lair west of here, in de Garden of the Loa. You should be able to see his totems. Run near dem to improve your speed. I will continue to purge de heretics from dis temple. Mind your manners around de loa, or he may rip your throat out.",starts={{npcID=126560,x=0.46,y=0.132,mapID=1165}},ends={{npcID=127576,x=0.498,y=0.334,mapID=1165}},coords={x=0.46,y=0.132,source="quest_giver",mapID=862},questType="standard"},
[47440] = {id=47440,name="Pa'ku, Master of Winds",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Come, ride Ata de Winglord with me, and he will take us to Pa'ku . Oh, and mind your manners around dat loa. Pa'ku has been known to drop followers she is not fond of from a really great height onto really hard stone.",starts={{npcID=126564,x=0.408,y=0.114,mapID=1165}},ends={{npcID=127489,x=0.498,y=0.334,mapID=1165}},coords={x=0.408,y=0.114,source="quest_giver",mapID=862},questType="standard"},
[47445] = {id=47445,name="The Zanchuli Council",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="You there, Speaker of de Horde. My spies have told me of dark heresies being practiced in our sacred temple of Zanchul. De king sent Loti and Raal to deal with de situation, but those two bickering council members are soft on their own followers. We need someone more... ruthlessly neutral. Go meet Wardruid Loti down at de Zocalo and she can tell you de rest.",starts={{npcID=122641,x=0.498,y=0.464,mapID=1165}},ends={{npcID=126560,x=0.46,y=0.132,mapID=1165}},coords={x=0.498,y=0.464,source="quest_giver",mapID=1165},questType="standard"},
[47491] = {id=47491,name="Remnants of the Damned",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Ever since da spirits have begun calling upon dis \"G'huun,\" me temple has been covered with da unbearable taint of da undead. Da undead be an abomination, but da bloodstones dat create dem be powerful. Dey could be of use ta Bwonsamdi . If ya wish ta show me ya fervor, den cleanse me temple of their filth and bring me their bloodstones.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=122688,x=0.396,y=0.246,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[47493] = {id=47493,name="A Lonely Spirit",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Da spirit of a child named Keula be wanderin' me temple grounds. Her ma'da gave her child up ta me long ago, she be thinkin' that a great sacrifice would spare her from me call, from going to da other side. Well she be right, I not claim her yet. But she be wrong too. Her child be da one to decide when ta be reunited with her ma'da, and it seem ta me dat da child be no longer be content ta wait. Dey both belong in my realm. Go, bring da child to her ma'da.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=126588,x=0.426,y=0.314,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[47495] = {id=47495,name="Insatiable Appetite [UNUSED]",level=1,requiredLevel=1,faction="horde",expansion=7,zoneID=8499,mapID=862,description="That was incredible! I've never seen such rapid growth! Your strange friend here be welcome to stay as long as he likes if he be willing to share his secret with the Kraal. As for you and your beast, he be looking awfully hungry again. I suspect you'll find it will take a lot more food to satisy him now. Good luck, Apprentice!",questType="standard"},
[47506] = {id=47506,name="REUSE",level=1,requiredLevel=1,faction="alliance",expansion=7,questType="standard"},
[47509] = {id=47509,name="Terrace of the Chosen",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="This betrayal has cut deep into the heart of Zandalar. Half of the Zanchuli Council and their followers have sided with Zul and his... blood god. Lucky for us not all of Zandalar is behind this betrayal. We need to topple Zul's cultists before they can rally too many to their cause. Zanchul is the place to start. Go and see if you can muster any of the Zandalari still loyal to their king.",questType="standard"},
[47512] = {id=47512,name="Nazmir",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="The blood trolls within the cursed swamp Nazmir threaten to destroy all of Zuldazar . Princess Talanji wants the Horde's help in an expedition to strike at the heart of the blood trolls and end their threat to Zuldazar .",ends={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=146335,x=0.498,y=0.464,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},questType="standard"},
[47514] = {id=47514,name="Zuldazar",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="King Rastakhan is an ancient ruler who is not quick to trust new allies. We must earn his trust if we are to earn his fleet. Zuldazar is the seat of power for the Zandalar empire and a good place to start in winning over these potential allies.",ends={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},questType="standard"},
[47518] = {id=47518,name="Raal",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="Crazzak is a traitor in priest's clothing who thinks if he tortures enough of us it will hurt our loa. Dey even have my husband Raal up on de apex of Zanchul. Normally I would say dey could have him, but dey are using his connection to Pa'ku to weaken de loa. Can't have dat. Let's get to de top of Zanchul and rescue my worthless husband.",starts={{npcID=123335,x=0.394,y=0.138,mapID=1165},{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},ends={{npcID=133324,x=0.436,y=0.074,mapID=1165}},coords={x=0.394,y=0.138,source="quest_giver",mapID=1165},questType="standard"},
[47520] = {id=47520,name="Walls Have Ears",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="Yazma, mistress of spies. Bah! A traitor who is into creepy crawlies. She chose to side with Zul, and she uses de children of her loa, Shadra, to watch and track everything we do. We have to kill all de spiders we see, or dat traitor Yazma will know every move we make.",starts={{npcID=123335,x=0.394,y=0.138,mapID=1165},{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},ends={{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},coords={x=0.394,y=0.138,source="quest_giver",mapID=1165},questType="standard"},
[47521] = {id=47521,name="Midnight in the Garden of the Loa",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Yazma and her henchtroll Vol'kaal have pulled most of their forces back to de Garden of de Loa. Something bad is afoot, I can feel it in my spirit. Pa'ku is in danger, along with all de loa who have followers dere. Come, let's fly dere and put an end to dese heresies.",starts={{npcID=133324,x=0.436,y=0.074,mapID=1165}},ends={{npcID=122760,x=0.506,y=0.296,mapID=862}},coords={x=0.436,y=0.074,source="quest_giver",mapID=862},questType="standard"},
[47522] = {id=47522,name="The Hunter",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Gonk is in danger. I can hear his call. My loa has saved my life so many times, it is about time I return de favor. Come, join me at de Lair of Gonk on de west side of de Garden of the Loa, and we will save a god.",starts={{npcID=122760,x=0.506,y=0.296,mapID=862}},ends={{npcID=124827,x=0.484,y=0.32,mapID=862}},coords={x=0.506,y=0.296,source="quest_giver",mapID=862},questType="standard"},
[47525] = {id=47525,name="Staying Hidden",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Dere be trouble brewin', mon. Da blood trolls be on da move! Dey set up a large camp nearby and have been sending a small force to da isle south of here. If dey discover our position while we be havin' no defenses, it gonna be game over! We need ta see what dey be up to and get rid of dem. Our best bet be ta investigate da isle south a here. Ya want ta join me? I be ready ta head out.",starts={{npcID=122991,x=0.674,y=0.42,mapID=863}},ends={{npcID=124376,x=0.686,y=0.466,mapID=863}},coords={x=0.674,y=0.42,source="quest_giver",mapID=863},questType="standard"},
[47528] = {id=47528,name="Mistress of Lies",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="If you are done dealing with dese peasant loa, den perhaps you can help with my own loa: Shadra. My \"high\" priestess, Yazma , is behind all of dis. If she is having her minions slay other loa, den I can only guess she is also trying to sacrifice my own loa as well. Shadra's shrine is on de northwest side of de Garden of the Loa. You must stop her from slaying de Mistress of Spies.",ends={{npcID=122760,x=0.506,y=0.296,mapID=862}},questType="standard"},
[47529] = {id=47529,name="Supernatural Support",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="The loa can bestow powerful boon's to their followers, aid that can be the difference between victory or defeat in our efforts here. Think carefully which of the two you would like to ask for their blessing. The loa will not give their assistance to those who are currently pledged to another loa.",questType="standard"},
[47540] = {id=47540,name="Totemic Restoration",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I am fed and my body is prepared. I can now be instilled with my power of old and for a time will be immune to their blood curses and leeching powers. Use the magic of the glowflies to channel my power from the totems into me. Soon you will see me restored. Then we will destroy the army that prepares across the river to take all that is mine by force.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47588] = {id=47588,name="King of the Hunt",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=8499,mapID=862,questType="standard"},
[47596] = {id=47596,name="There Is No Plan \"B\"",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Look, I'll be honest with you. Our mech, the A.M.O.D., was the best we've ever made. It was mobile. It was powerful. It was one of a kind! What I'm trying to say is, without it, our whole plan is ruined! We have to salvage and rebuild it! That big oaf of a sea giant broke the A.M.O.D. apart and scattered its pieces all over the shore. Find its parts and I'll try to hammer them back together.",starts={{npcID=123548,x=0.822,y=0.272,mapID=863}},ends={{npcID=123548,x=0.822,y=0.272,mapID=863}},coords={x=0.822,y=0.272,source="quest_giver",mapID=863},questType="standard"},
[47597] = {id=47597,name="No Goblin Left Behind",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Our mission is dead in the water unless we move fast! I've found the perfect spot for a new base. While I secure the location, I need you to rescue the team and bring them back. We've trained for this a million times. Just direct them toward the rendezvous point and they'll find the way. We don't have much time, let's go!",starts={{npcID=123178,x=0.746,y=0.388,mapID=863}},ends={{npcID=123544,x=0.822,y=0.272,mapID=863}},coords={x=0.746,y=0.388,source="quest_giver",mapID=863},questType="standard"},
[47598] = {id=47598,name="Pilfering and Fencing",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Our ships are sunk. Our A.M.O.D.'s gone. We've lost a LOT on this mission... and the Bilgewater Cartel don't offer insurance. The debt collectors will be all over us! We gotta make up for these losses. The beach is swarmin' with naga tryin' to collect artifacts from the ruins. How 'bout we grab some of that treasure and make back our money? I'm sure we could find a buyer willing to take 'em off our hands. We'll split the proceeds 80/20. Sounds fair to me.",starts={{npcID=123545,x=0.822,y=0.272,mapID=863}},ends={{npcID=123545,x=0.822,y=0.272,mapID=863}},coords={x=0.822,y=0.272,source="quest_giver",mapID=863},questType="standard"},
[47599] = {id=47599,name="Revenge: Served Hot",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Look, the boss might be keeping a level head here, but we should show these naga what happens when you mess with the Gob Squad. Don't you agree? The naga are sending their behemoths to destroy what's left of our ship. Why don't you take my rocket launcher and make an example out of them. That'll send the message loud and clear!",starts={{npcID=123436,x=0.746,y=0.39,mapID=863},{npcID=123526,x=0.746,y=0.39,mapID=863}},ends={{npcID=123548,x=0.822,y=0.272,mapID=863}},coords={x=0.746,y=0.39,source="quest_giver",mapID=863},questType="standard"},
[47601] = {id=47601,name="Field Evaluation",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We got the A.M.O.D. back together. It's a fine piece of equipment, but we're gonna have to give it a tune up. We don't want to end up digging shrapnel out of our rears. Lucky for us, there are a few naga camps remaining along with the giant that broke the gun in the first place. They'll be great for target practice. We'll deploy the A.M.O.D. just outside the building here. After we deploy, go man it. I'll have you fire a few rounds while I tune its gun. Everything'll be fine... unless it isn't.",starts={{npcID=123544,x=0.822,y=0.272,mapID=863}},ends={{npcID=123878,x=0.814,y=0.26,mapID=863}},coords={x=0.822,y=0.272,source="quest_giver",mapID=863},questType="standard"},
[47602] = {id=47602,name="Ready For Action",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="It's gonna take a bit to get the gun chassis set up. Who knew lifting big equipment could be so hard? In the meantime, why don't you go check back with your friends. Make sure everything's ready on their end. I'd hate to drive this gun into ANOTHER ambush because they're not ready.",starts={{npcID=123878,x=0.814,y=0.26,mapID=863}},ends={{npcID=126213,x=0.674,y=0.422,mapID=863}},coords={x=0.814,y=0.26,source="quest_giver",mapID=863},questType="standard"},
[47621] = {id=47621,name="A True Loa Feast",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="The blood troll attacks have not stopped until now. They have weakened me significantly and I need to get my strength back. My followers used to bring me offerings of meat from the nearby lands. Go and bring back a mighty feast. My strength will return and we will stop these attacks once and for all.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47622] = {id=47622,name="A Magical Glow",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Long ago when the trolls began listening to the whispering darkness, I instilled portions of my power into the totems that surround my lair. I need that power now. In the swamps north of here are glowflies. Their magical essence will aid me in drawing the stored power from the totems. Collect them and return. Then you will see what I was capable of at the height of my strength.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47623] = {id=47623,name="The Last Witch Doctor of Krag'wa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I am Krag'wa, the once mighty. Curse the blood trolls and their dark god! They have slain my worshippers until only Zentimo remained, and now even he is gone. I want revenge on the blood trolls, but first I must honor the last of my witch doctors. As I have no others, I must request you perform the ritual. Then we can talk of revenge.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47631] = {id=47631,name="Rendezvous with the Libation",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I be honest wit' ya, mon. I be havin' little patience for goblins and their antics. Go meet with their leader and ensure dat his crew and da weapon be ready for da assault. Zuldazar gonna be overrun by da blood trolls if we fail. Good luck, !",starts={{npcID=131213,x=0.674,y=0.422,mapID=863}},ends={{npcID=123178,x=0.746,y=0.388,mapID=863}},coords={x=0.674,y=0.422,source="quest_giver",mapID=863},questType="standard"},
[47642] = {id=47642,name="Soul Crystal",level=45,requiredLevel=45,faction="both",expansion=7,description="Keep the Ruby Shrinewardens occupied. I shall carry out our master's attack from within the great tree itself.",questType="standard"},
[47643] = {id=47643,name="The Ancients' Wisdom",level=45,requiredLevel=45,faction="both",expansion=7,description="The three ancients left three clues: \"...the great nightmare...\" \"...by the water...\" \"...within the dragon's palm...\" Perhaps Chromie 's attacker lies in the place the ancients describe?",questType="standard"},
[47644] = {id=47644,name="Demonic Corestone",level=45,requiredLevel=45,faction="both",expansion=7,description="Yes, master. It shall be done, at the exact time that you specified. The bronze dragon will see nothing. One shot from outside the Obsidian Dragonshrine is all I require.",questType="standard"},
[47645] = {id=47645,name="Voidcallers' Scroll",level=45,requiredLevel=45,faction="both",expansion=7,description="The time is nigh. The invocation will take place above the azure shrine. The void will swallow the bronze dragon. Our master has spoken, and we obey.",questType="standard"},
[47659] = {id=47659,name="Hunt the Hunter",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Please, help us. De Frogmarsh is under siege! My master, de great loa, Krag'wa, is not willing to bend to de will of de blood trolls and their dark god. So now, dey are taking his power by force! Dey are slaying his children and taking his totems of power. Dey will even take Krag'wa and sacrifice him if we are not able to end dis madness! Stop dem! Slay their leader. Perhaps dat will slow dem down for a while. It will give me time to find a more permanent solution.",starts={{npcID=124376,x=0.686,y=0.466,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.686,y=0.466,source="quest_giver",mapID=863},questType="standard"},
[47660] = {id=47660,name="Fallen Idols",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De blood trolls seek to weaken Krag'wa and take his power. Dey steal his idols of power to crack open and feed their magic. Salvage what idols you can. Dey will be needed to make Krag'wa strong. Strong enough to fight dem off once and for all.",starts={{npcID=124376,x=0.686,y=0.466,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.686,y=0.466,source="quest_giver",mapID=863},questType="standard"},
[47695] = {id=47695,name="Sound the Alarm",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,mapID=895,description="Sirens are nothing but trouble! All they do is capture our men, never to be seen again. How is anybody supposed to get their goods to Boralus quickly with them around? Since you're already going down there... mind culling their numbers a bit?",questType="standard"},
[47696] = {id=47696,name="Krag'wa the Terrible",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Your previous attack has angered the blood trolls. They now send an army to take everything. They are too late! I am Krag'wa! I will not be eaten, I do the eating! Meet me at the edge of Razorjaw River. You will bear witness to my power, and I will bear witness to yours.",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47697] = {id=47697,name="Krag'wa's Aid",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Well done, ! Before we left, I heard dat Princess Talanji be headed ta Gloom Hollow . She should be dere by now. We better be headin' back. She would want ta hear da tale of ya success!",starts={{npcID=124641,x=0.752,y=0.566,mapID=863}},ends={{npcID=126213,x=0.674,y=0.422,mapID=863}},coords={x=0.752,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[47711] = {id=47711,name="Head of the Viper",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="While I was scouting out the area, I saw a big armored naga bossing the rest of the snakes around. Call it a hunch, but I'm pretty sure he's their leader. As long as the Naga have a commander our operations here will be threatened. Take him out.",starts={{npcID=123544,x=0.822,y=0.272,mapID=863}},ends={{npcID=123544,x=0.822,y=0.272,mapID=863}},coords={x=0.822,y=0.272,source="quest_giver",mapID=863},questType="standard"},
[47733] = {id=47733,name="The Loa-Speaker's Betrayal",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Listen, stranger. I don't have a lot of time left. I was in de village when Zolani brought de king to us. Said to keep it a secret, or else Zul would find us. Look around. Dey found us! But I know... I know it was not de prophet's doing. Our loa-speaker gave Zolani her pretty words, said she would help, then turned around and sold us out. It is Kihara's fault dat we are dying now. She brought dis upon us! Kill her... Make her pay!",starts={{npcID=138520,x=0.792,y=0.166,mapID=862}},ends={{npcID=124083,x=0.766,y=0.162,mapID=862}},coords={x=0.792,y=0.166,source="quest_giver",mapID=862},questType="standard"},
[47734] = {id=47734,name="Partners in Heresy",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Rezan struggles against his bonds, but we cannot reach him. De mogu dat Zul called here have raised a shield dat rejects my magic. Find and kill de creatures dat stand between me and my loa. I must gather myself for de fight to come. They will know de wrath of TWO kings before dis day is done.",starts={{npcID=124655,x=0.72,y=0.21,mapID=862}},ends={{npcID=124655,x=0.72,y=0.21,mapID=862}},coords={x=0.72,y=0.21,source="quest_giver",mapID=862},questType="standard"},
[47735] = {id=47735,name="Ancient Tortollan Remedies",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Ah, yes, the situation is urgent. We must act quickly, but not hastily. There is a way to save Rastakhan, but it will require three very specific ingredients. Listen well, young one. The first, foam bubbling from the mouth of a crab. The older, the better. The second, the spine of a puffer fish. Venomous! The third, a brutosaur scale . Why? These are the secrets of my people, . Longevity is cultivated like the rarest of flowers... carefully, and with much practice.",starts={{npcID=124063,x=0.764,y=0.16,mapID=862}},ends={{npcID=124063,x=0.764,y=0.16,mapID=862}},coords={x=0.764,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[47736] = {id=47736,name="Heads Will Roll",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Zul's forces try to lay claim to de loa of kings's temple. You must teach dese traitors de meaning of their actions. Sweep de temple of de filth dat defiles it. Destroy those who spit in de face of de loa. Bring me their heads so I may remind others of what happens to those who betray their faith and their king. When you are finished dealing with de unworthy, come find us. Rezan's altar lies deep within de temple grounds. In Rastakhan's name, heads will roll!",starts={{npcID=124656,x=0.748,y=0.248,mapID=862}},ends={{npcID=124656,x=0.748,y=0.248,mapID=862}},coords={x=0.748,y=0.248,source="quest_giver",mapID=862},questType="standard"},
[47737] = {id=47737,name="The Temple of Rezan",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="De chronicler's words are dire. If Zul truly does wish to sacrifice Rezan... Dis will not come to pass! I will defend my loa with my life. Come, , we go to de Temple of Rezan. We must stop dis heresy at once!",starts={{npcID=124062,x=0.766,y=0.16,mapID=862}},ends={{npcID=124655,x=0.72,y=0.21,mapID=862}},coords={x=0.766,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[47738] = {id=47738,name="The Will of the Loa",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Jol's remedy healed Rastakhan's flesh. But his spirit is still lost. Dere is only one thing stopping him now. Death. He is walking in Bwonsamdi's shadow. For most, dere would be nothing to be done. But... he is bound to another loa. A loa who gives life to his faithful. You must call on Rezan , loa of kings, and ask him to claim back Rastakhan's soul. Up de path, you will find my tent. Place dis idol and wait dere. If we are lucky, he will aid us. If not... It was nice knowing you.",starts={{npcID=132637,x=0.764,y=0.16,mapID=862}},ends={{npcID=124062,x=0.766,y=0.16,mapID=862}},coords={x=0.764,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[47739] = {id=47739,name="The Scent of Vengeance",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I know my king, and I know he is not weak willed. His spirit struggles under de weight of dis betrayal, and confusion roots his spirit too close to death for my comfort. We will need to remind him of his purpose. His anger. I have heard shouts of terror from de village below. Zul's followers torment Zeb'ahari while dey hunt for him. Slay those who would harm his people and bring me their blood. Perhaps de scent of vengeance can revive de devilsaur inside ol' Rastakhan.",starts={{npcID=132637,x=0.764,y=0.16,mapID=862}},ends={{npcID=132637,x=0.764,y=0.16,mapID=862}},coords={x=0.764,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[47740] = {id=47740,name="House of the King",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I hear Rezan's call. I will answer, but first you must help me. Our loa give us many boons, and we repay dem in worship. Offerings, sacrifices, and idols are our tools to earn favor, but dey are much more to our loa. Dey are sources of strength. Zul's dogs have begun to corrupt de great golden statues dedicated to Rezan. Even now, I can feel his power dwindling. Stop dem. Cleanse de idols to de great hunter. Teach dem to respect de house of de king.",starts={{npcID=124655,x=0.72,y=0.21,mapID=862}},ends={{npcID=124655,x=0.72,y=0.21,mapID=862}},coords={x=0.72,y=0.21,source="quest_giver",mapID=862},questType="standard"},
[47741] = {id=47741,name="To Sacrifice a Loa",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Rezan 's power is fading. My usurpers have nearly completed their task. I have read of de horrors of Zul'Drak, and I have seen de results of dese acts. To think one of my own people would bring dis heresy here is... unimaginable. Come! We will end dis traitor who spits in de face of all loa! Di chuka Rezan !",starts={{npcID=124655,x=0.72,y=0.21,mapID=862}},ends={{npcID=124948,x=0.708,y=0.298,mapID=862}},coords={x=0.72,y=0.21,source="quest_giver",mapID=862},questType="standard"},
[47742] = {id=47742,name="Zul's Mutiny",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9772,description="A ship such as Rastakhan's Might does not readily sail without her crew. Dat means de Zandalari aboard have succumbed to Zul's machinations and have betrayed their king as surely as he has. Board my ship. Kill those who think to rise against their king. We will take no prisoners. De punishment for de crime of mutiny is death!",starts={{npcID=124062,x=0.766,y=0.16,mapID=862}},ends={{npcID=124062,x=0.766,y=0.16,mapID=862}},coords={x=0.766,y=0.16,source="quest_giver",zoneID=8499},questType="standard"},
