[47857] = {id=47857,name="REUSE ME",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8701,mapID=882,description="Hey you've finished part 1 of the Velen arc. Stop here. Nothing past this point is done.",questType="standard"},
[47868] = {id=47868,name="The Necropolis",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="A deal is a deal, and I pay my debts. Bwonsamdi is a mighty loa and you are going to need a powerful ritual to obtain his attention. You are in luck. I already know exactly what needs to be done. Bwonsamdi's temple, de Necropolis, is just to de north. Meet me in de courtyard and we shall see about obtaining an audience with de loa of death.",starts={{npcID=124428,x=0.396,y=0.438,mapID=863}},ends={{npcID=124513,x=0.396,y=0.326,mapID=863}},coords={x=0.396,y=0.438,source="quest_giver",mapID=863},questType="standard"},
[47880] = {id=47880,name="A Tribute for Death",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Everything for de ritual is together. Now, it is time to begin. For dis to work, I must chant de words of old. It is an exhausting task, so I need you to take my mojo fetish and draw de ritual circle, then beat upon de drums. If all goes well, Bwonsamdi may invite us into de temple. If not, our souls are forfeit. Let's not make any mistakes.",starts={{npcID=124513,x=0.396,y=0.326,mapID=863}},ends={{npcID=122688,x=0.396,y=0.246,mapID=863}},coords={x=0.396,y=0.326,source="quest_giver",mapID=863},questType="standard"},
[47895] = {id=47895,name="Bert's Bots",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=1,mapID=27,description="If I'm going to clean up Gnomeregan, I've got to be ready to battle all manner of rat, roach, and potentially even the dreaded mutant rat-roach. What I'm saying is that I need to put these bots to the test! A real, live-action field demo. Are your pets up for a code review?",questType="standard"},
[47897] = {id=47897,name="Zanchuli Traitors",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dey are trying to cast down our loa, claiming dem to be false gods. Dey have turned to de old ways of blood, sacrifice, and subjugation. I cannot even begin to say how offensive dis is. Kill any of dese traitors you find.",starts={{npcID=124629,x=0.426,y=0.216,mapID=1165}},ends={{npcID=123335,x=0.394,y=0.138,mapID=1165},{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},coords={x=0.426,y=0.216,source="quest_giver",mapID=862},questType="standard"},
[47915] = {id=47915,name="Rescuing the Taken",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8726,mapID=1165,description="We are doing our best to contain de fighting in Zanchul and not let it spill out into de other terraces, but we can't hold for long. If you are going to help, start by freeing Wardruid Loti . Dey are trying to break her on de platform above with a dark ritual. Her soul is bound to a fetish. You must find dat fetish if you are going to free her.",starts={{npcID=124629,x=0.426,y=0.216,mapID=1165}},ends={{npcID=123335,x=0.394,y=0.138,mapID=1165},{npcID=133302,x=0.382,y=0.074,mapID=1165},{npcID=133302,x=0.392,y=0.561,mapID=1165},{npcID=133302,x=0.449,y=0.338,mapID=1165}},coords={x=0.426,y=0.216,source="quest_giver",mapID=1165},questType="standard"},
