[47952] = {id=47952,name="The Missing Fleet",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="The tidesage order has a sizable monastery right here in Boralus. I say we start our search for the fleet there. Someone there has to know something, right? You don't just lose the entire legendary Kul Tiran fleet on accident! We'll need to take a ferry over to the monastery. Make sure you bring your pass with you!",starts={{npcID=121235,x=0.68,y=0.22,mapID=1161}},ends={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},coords={x=0.68,y=0.22,source="quest_giver",mapID=942},questType="standard"},
[47962] = {id=47962,name="Stormsong Valley",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="The Kul Tiran fleet has been lost at sea. The tidesages of Stormsong, with their mystical oceanic magic, may be our only way to locate the fleet of legend.",ends={{npcID=121235,x=0.68,y=0.22,mapID=1161}},questType="standard"},
[47963] = {id=47963,name="The Ancient One",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dis is far worse than I thought. Pa'ku is crying out in my mind. Dey are doing something to her. Something old and terrible, smelling of de old ways. She is nearby, just south of here. Come, $p, meet me at Pa'ku 's roost and we'll rescue her.",starts={{npcID=133653,x=0.506,y=0.296,mapID=862}},ends={{npcID=124756,x=0.496,y=0.266,mapID=862}},coords={x=0.506,y=0.296,source="quest_giver",mapID=862},questType="standard"},
[47994] = {id=47994,name="Forming a Bond",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,starts={{npcID=121263,x=0.62,y=0.868,mapID=830},{npcID=121263,x=0.428,y=0.238,mapID=830}},ends={{npcID=121263,x=0.62,y=0.868,mapID=830},{npcID=121263,x=0.428,y=0.238,mapID=830}},coords={x=0.62,y=0.868,source="quest_giver",mapID=885},questType="standard"},
