[48023] = {id=48023,name="Orders Received",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We need ta be knowin' who be leadin' da naga in snatchin' all dese cute frogs. Dey got chests around here dat have some kind of scroll dey be readin'. Da ladies be tellin' da men to remember dem orders. Get me some of dem scrolls so we can be seein' who be callin' da shots.",questType="standard"},
