[48176] = {id=48176,name="Big Trouble in Little Tortolla",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I received a message asking for a sword hand in Little Tortolla. The Tortollan Seekers there are greatly admired by King Rastakhan and have special privileges assigned to them. Go see what they want and you will have the favor of the King. And $p, be respectful. Tortollans live long enough they can hold your children's children accountable for your actions.",questType="standard"},
[48230] = {id=48230,name="Fragment of the Past",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8701,mapID=882,description="Captain Fareeya would be able to tell you more about the crystal.>",questType="standard"},
[48278] = {id=48278,name="Fate of the Life-Binder",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8574,mapID=830,description="I don't even want to think about what happens if Aggramar can find Eonar's spirit before we do. The fate of far more'n Azeroth may hinge on her safety. Let Turalyon know what we saw right away. We're going to need to bring all we can to bear to save her.",questType="standard"},
[48281] = {id=48281,name="Tracking Quest",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8574,mapID=830,questType="standard"},
[48296] = {id=48296,name="The Soulhunter",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7834,mapID=702,description="Imonar is the deadliest bounty hunter the Twisting Nether has ever produced. Find a pit to throw him down.",ends={{npcID=96746,x=0.33,y=0.6,mapID=726},{npcID=103023,x=0.43,y=0.468,mapID=739},{npcID=106199,x=0.666,y=0.46,mapID=717}},questType="raid"},
[48297] = {id=48297,name="The Burning Coven",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7834,mapID=702,description="Not even a Titan can endure their torture. Bring an end to the Coven of Shivarra.",ends={{npcID=98002,x=0.528,y=0.514,mapID=747},{npcID=106199,x=0.666,y=0.46,mapID=717}},questType="raid"},
