[48395] = {id=48395,name="Whispers from the Shadows",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=7503,mapID=650,description="Hero, we have a problem. The ancient Necrodark cult has returned. When Dargrul was the Underking he would quell these cultists whenever they appeared, keeping them from exploring the vault of Neltharion. But now, with Dargrul gone, they are sieging the vault in force. We must stop them before they find what they are looking for.",questType="standard"},
