[48435] = {id=48435,name="The Spiritwalkers",level=40,requiredLevel=40,faction="none",expansion=7,description="Ebonhorn is in the care of Spiritwalker Graysky. A cure is proving elusive... he has asked for your help. Please speak with him at once, . The spiritwalkers are the keepers of our past. I pray the answer lies somewhere in the ancient truths they hold.",questType="standard"},
[48452] = {id=48452,name="The Red Market",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="You came with de Princess Talanji? I need a hand with a most unsavory task. Crimson cultists have made demselves a market for blood magic. Dis is bad, mon. Dis is very bad indeed. I need you to go down dese steps and bring back any evidence you can of blood practices. And destroy their chalice. Big chalice. Don't forget de chalice.",starts={{npcID=126148,x=0.442,y=0.82,mapID=1165}},ends={{npcID=126148,x=0.442,y=0.82,mapID=1165}},coords={x=0.442,y=0.82,source="quest_giver",mapID=1165},questType="standard"},
