[48535] = {id=48535,name="Nazmir, the Forbidden Swamp",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Da Horde promised Princess Talanji dat we be dealin' with dese blood trolls in Nazmir before dey can attack Zuldazar. Grab a pterrordax and get over ta Talanji's camp in Nazmir . We be waitin' for ya there. Make sure ya ready, . Dere be no civilization in Nazmir , just us and whatever be lurkin' dere.",starts={{npcID=126549,x=0.516,y=0.412,mapID=1165}},ends={{npcID=120904,x=0.43,y=0.86,mapID=863}},coords={x=0.516,y=0.412,source="quest_giver",mapID=863},questType="standard"},
