[48555] = {id=48555,name="We Can Salvage the Seeds",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=16365,mapID=2512,description="I've studied the flora within the terrace extensively. Once a thistlevine completely dries out, it's too late for the plant to be saved. Its seeds are still viable, however. Under the right conditions, they can be used to cultivate new, healthy thistlevines. Salvage seeds from the carnivorous thistlevines that can no longer be saved, and plant them within the fertile mounds of dirt. The thistlevine plant is extremely quick to sprout, so the terrace should be filled with seedlings in no time!",starts={{npcID=126814,x=0.538,y=0.694,mapID=864}},ends={{npcID=126814,x=0.538,y=0.694,mapID=864}},coords={x=0.538,y=0.694,source="quest_giver",mapID=2512},questType="standard"},
