[48632] = {id=48632,name="Void Extract",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8701,mapID=882,description="The void calls to its own. When they are destroyed, powerful creatures of shadow leave behind vast amounts of undiluted void. It's lure is powerful enough to draw out the noxious influence polluting my brethren. Not all survive the purge, but the alternative is worse than death - you've seen the voidscarred roaming Oranaar. Destroy a powerful agent of shadow, collect its essence, and bring it to me. I will use it draw out the corruption.",questType="standard"},
[48653] = {id=48653,name="A Bejeweled Prison",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Nazmir and return the gem to it's rightful resting place, wherever that may be.>",questType="standard"},
