[48699] = {id=48699,name="Sneaking into Zalamar",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I know you might think nothing has changed, but trust me, de voodoo worked... I think. You should transform into one of de blood trolls when you are near Zalamar, one of their villages. Jo'chunga should be dere somewhere, most likely near a large gathering of blood trolls. Find Jo'chunga and tell him I have sent you, den see what he knows about de situation dere.",starts={{npcID=122795,x=0.396,y=0.438,mapID=863}},ends={{npcID=127391,x=0.334,y=0.458,mapID=863}},coords={x=0.396,y=0.438,source="quest_giver",mapID=863},questType="standard"},
