[48758] = {id=48758,name="Disgustingly Damp Flower",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="Rummaging for pollen as usual, you use the harvesting technique you learned from the bees. However, when you pull your hand away from the flower, you find that there is no pollen on your gloves. Looking inside the swirl of petals, despite it being a mature flower, you see that there is no pollen at all within it. Upon closer inspection you see that the flower is filled with a viscous liquid. Could the flower have done this? While unpleasant to touch, you carefully pluck the flower to show Declan.",ends={{npcID=136096,x=0.704,y=0.06,mapID=1161}},questType="standard"},
[48759] = {id=48759,name="Akunda's Bite - Rank 2 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,description="Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.",questType="standard"},
[48760] = {id=48760,name="Akunda's Bite - Rank 3 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,description="Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.",questType="standard"},
[48763] = {id=48763,name="The Frigid Boon",level=10,requiredLevel=10,faction="none",expansion=7,description="While harvesting this winter's bite, you managed to pluck the flower without breaking any petals, a feat you had not accomplished before. Taking a quick mental note of every detail about yourself and your surroundings, one point sticks out to you. The heat from your breath appears to have made the petals supple enough to bend instead of break. You also believe that this may be a way to prevent the flower from activating its defensive cold blast. If that is the case, it could be extremely useful.",questType="standard"},
[48765] = {id=48765,name="Aromatic Pollen - Rank 2 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,description="Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.",questType="standard"},
[48766] = {id=48766,name="Aromatic Pollen - Rank 3 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,description="Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.",questType="standard"},
[48767] = {id=48767,name="Seams Familiar",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="You find a necklace in the shape of an anchor with the name \"Cabot\" etched in a banner. The name immediately brings up Myra Cabot , the mining trainer in Boralus. The condition of the necklace makes it look like it has been well maintained. She probably wants it back.",ends={{npcID=136091,x=0.75,y=0.076,mapID=1161}},questType="standard"},
[48771] = {id=48771,name="Herb 07 - Rare - Rank 2 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,description="Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.",questType="standard"},
[48772] = {id=48772,name="Herb 07 - Rare - Rank 3 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,description="Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.",questType="standard"},
[48800] = {id=48800,name="Mark of the Bat",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Dere are three witches in de camp who have talismans empowered by Hir'eek. I need you to get those talismans for me to use after you prove my poison works perfectly. I will use de essence of Hir'eek within de talismans to make my own poison strong enough to use against de loa. If my poison doesn't work... well, I do not want to think about dat. It will work, because we need it to. Just go get de talismans. I will be here, hiding from de blood trolls.",starts={{npcID=127391,x=0.334,y=0.458,mapID=863}},ends={{npcID=127391,x=0.334,y=0.458,mapID=863}},coords={x=0.334,y=0.458,source="quest_giver",mapID=863},questType="standard"},
[48801] = {id=48801,name="Isolating Zalamar",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Hir'eek, de loa of bats, has been corrupted by G'huun! We will get no help from him. We only have one option if dey have a loa on their side... we must kill Hir'eek. It's crazy, and we will both probably die, but I have a plan. We need to isolate dis place first. De blood trolls have wardrummers who sound an alarm if anything happens here. We need dem gone... but you have to be sneaky about it. You have a good disguise, so you can order de drummers to go leave their posts.",starts={{npcID=127391,x=0.334,y=0.458,mapID=863}},ends={{npcID=127391,x=0.334,y=0.458,mapID=863}},coords={x=0.334,y=0.458,source="quest_giver",mapID=863},questType="standard"},
[48808] = {id=48808,name="Thesis Statement",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,mapID=896,description="My thesis! Those smelly troggs took my thesis paper and fed it to their boars! Can you believe it!? I worked forever on it! Two whole days! If I don't get it back I'm ruined! Absolutely ruined! Please get my thesis paper back for me?",questType="standard"},
