[48890] = {id=48890,name="How to Be a Blood Troll",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="You will have to blend in if you don't want anyone getting suspicious. This won't be pretty. Dere are drudges around de camp who have been tied up as part of a ritual. Dey get beaten as a test to make dem stronger. Any who fail de ritual are sacrificed. De ones who succeed are allowed to fight de Zandalari. If you are going to blend in, you need to \"test\" dese drudges as part of de ritual. It's weird, but dat's how dey work.",starts={{npcID=127391,x=0.334,y=0.458,mapID=863}},ends={{npcID=127391,x=0.334,y=0.458,mapID=863}},coords={x=0.334,y=0.458,source="quest_giver",mapID=863},questType="standard"},
[48897] = {id=48897,name="The Bargain is Struck",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Now dat you have declared a patron loa for your time here in Zuldazar , you should inform de king of your decision. He will appreciate dat you chose to follow de mighty Gonk.",starts={{npcID=127576,x=0.498,y=0.334,mapID=1165}},ends={{npcID=120740,x=0.498,y=0.464,mapID=1165}},coords={x=0.498,y=0.334,source="quest_giver",mapID=1165},questType="standard"},
[48905] = {id=48905,name="Unappreciated Scrolls",level=20,requiredLevel=20,faction="none",expansion=7,zoneID=8500,mapID=863,description="Since you're here in Natha'vor, you might as well help out the rest of the pilgrimage with a problem. These trolls have stolen several of our scrolls. Why they would, I have no idea, I doubt they're smart enough to even read. I want you to get them back. I'm not young anymore, I can't just be casting magic off the top of my head! Especially healing magic... which I'm sure Shoak is going to need when you rescue his dumb shell.",questType="standard"},
[48906] = {id=48906,name="Tracking Quest",level=0,requiredLevel=0,faction="both",expansion=7,zoneID=8899,mapID=885,questType="standard"},
