[48949] = {id=48949,name="Weeds of the Mire",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Help me... weak... can't heal... Graveweed... help... more... please...",questType="standard"},
[48954] = {id=48954,name="Blood of a Titan",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,mapID=627,questType="standard"},
[48964] = {id=48964,name="Immortal Ace",level=1,requiredLevel=1,faction="both",expansion=7,zoneID=8899,mapID=885,description="An effigy. The Many-Faced One requires it. Steal from the Imps. Steal from the Fiends. Steal from the Ur'zul. He comes.",questType="standard"},
[48973] = {id=48973,name="Paragon of Argussian Reach",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,description="Your allies among the Argussian Reach have requested your presence. They wish to reward you for your continued efforts on their behalf.",ends={{npcID=127151,x=0.638,y=0.894,mapID=830},{npcID=127151,x=0.67,y=0.576,mapID=830}},questType="standard"},
[48974] = {id=48974,name="Paragon of the Army of the Light",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,description="Your allies in the Army of the Light would like to thank you for your continued support. They await you on the Vindicaar.",ends={{npcID=127120,x=0.62,y=0.908,mapID=830},{npcID=127120,x=0.44,y=0.728,mapID=830}},questType="standard"},
[49007] = {id=49007,name="Commander on Deck!",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=8899,mapID=885,questType="standard"},
[49027] = {id=49027,name="Targets of Opportunity: Terminus",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=8899,mapID=885,description="Those Legion ships are a problem, . Even now they dock perilously close to the Vindicaar, threatening us with their presence. Sometimes when fighting the Legion it is better to go straight to the top rather than thinning their numbers. Go to the shipyards of Terminus and slay their officers and commanders. That should rattle their forces and put them back on the defensive.",questType="standard"},
[49029] = {id=49029,name="Invasion of Space",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=8899,mapID=885,description="We are on the Legion home world, but we must not let ourselves get caught unawares. These invasion points can bolster their forces and ruin our plans. By defeating them on their territory we also damage their command and infrastructure. Slay the commanders and stop their invading forces. The fight to push the Legion back begins now!",questType="standard"},
[49030] = {id=49030,name="Fragments of the Abyss",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=8899,mapID=885,description="Our scouts have delivered a disturbing report, champion. Some of the more powerful creatures of the Void are carrying powerful crystals that augment their abilities. They now pose a greater threat than before, and we can no longer ignore them. Find these void-tainted monstrosities and take their crystals. We will find a way to dispose of them safely.",questType="standard"},
[49031] = {id=49031,name="Out With The Inquisitors",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=8899,mapID=885,description="Of all of the demons at the Legion's disposal, the inquisitors are some of the most terrible. Even feared by some of the lesser demons, these monsters delight in cruelty and torturing their captives. Inquisitors revel in the terror they cause, but perhaps we can make that work to our advantage. Find the most powerful inquisitors you can and defeat them. Their deaths will not only improve the morale of our troops, but also send a message to their lesser forces.",questType="standard"},
[49033] = {id=49033,name="REUSE ME",level=1,requiredLevel=1,faction="both",expansion=7,questType="standard"},
[49059] = {id=49059,name="The Bones of Xibala",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8499,mapID=862,description="Our allies in the Explorers' League have alerted us to an exciting find. They have set up camp in the Xibala region of Zuldazar . Make your way to the camp and help them uncover anything that may advance our cause.",questType="standard"},
[49064] = {id=49064,name="Torga, the Turtle Loa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Name's Lashk . We're not here to join any cause, we just want to hear Torga's legendary stories. I don't know if he'll help, but you can try persuading Torga, loa of the turtles, and see if he'll help you fight these blood trolls. You can join on our pilgrimage to Torga, just keep quiet. Follow the path and find Kisha , she'll tell you where to go.",starts={{npcID=127958,x=0.556,y=0.394,mapID=863},{npcID=127960,x=0.584,y=0.138,mapID=863}},ends={{npcID=127961,x=0.584,y=0.138,mapID=863}},coords={x=0.556,y=0.394,source="quest_giver",mapID=863},questType="standard"},
[49067] = {id=49067,name="Beseeching Bwonsamdi",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We must talk to Torga's spirit and find out what exactly happened here... and how we can stop it. Hrm, you mentioned dat you are linked to Bwonsamdi now. It is time to test dat link. We need Bwonsamdi to get us Torga's spirit.",starts={{npcID=127961,x=0.584,y=0.138,mapID=863}},ends={{npcID=127961,x=0.584,y=0.138,mapID=863}},coords={x=0.584,y=0.138,source="quest_giver",mapID=863},questType="standard"},
[49070] = {id=49070,name="Souls for the Death Loa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Dere be blood trolls swarmin' all over dis place. Dey really be pickin' Torga clean, even eatin' his meat. Dat be dark, even for me. Da souls of dese blood trolls be corrupted by eatin' a loa. Somethin' ya should be rememberin' for future reference. Dese souls be worth a lot ta me, more dan just da normal souls of dese blood trolls. Get me da corrupted souls of dese blood trolls and I be callin' da spirit of Torga to ya.",starts={{npcID=128096,x=0.566,y=0.266,mapID=863}},ends={{npcID=128096,x=0.566,y=0.266,mapID=863}},coords={x=0.566,y=0.266,source="quest_giver",mapID=863},questType="standard"},
[49071] = {id=49071,name="Dreadtick Combustion",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="This whole thing is crazy, you know that? I don't think any story can top this one... Bah! Do you hear that insufferable sound? It's those stupid dreadticks sucking on Torga's meat. Makes my skin crawl! What? You can't hear it? Meh, trust me, they're around, and they need to be taken care of. Here, take this scroll. We've had to deal with these dumb insects in the past. Read it near them and it'll cause them to explode.",starts={{npcID=127960,x=0.584,y=0.138,mapID=863}},ends={{npcID=127960,x=0.584,y=0.138,mapID=863}},coords={x=0.584,y=0.138,source="quest_giver",mapID=863},questType="standard"},
[49073] = {id=49073,name="Ritualistic Denial",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I can't believe we're dealing with a death loa, a DEAD loa, and blood trolls. This isn't what I had planned today! Look, some of the other tortollans have said there are some blood rituals going on. They were spooked and started heading for the coast when they saw it. Take this scroll and read it near any blood rituals . It should cause it to disperse. Be careful with my scroll! It's old and they don't make them like they used to.",questType="standard"},
[49078] = {id=49078,name="Poisoning the Brood",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Now we have room for our plan to kill Hir'eek. You see, , my specialty is in making potions and poisons. I am working on a poison to use on Hir'eek, when de time comes. I have no idea if it will work or not. I want you to take what I already made and use it on de bats around here. It should kill dem instantly. If it works, den I can make it stronger with my voodoo and give us a chance at killing Hir'eek.",starts={{npcID=127391,x=0.334,y=0.458,mapID=863}},ends={{npcID=127391,x=0.334,y=0.458,mapID=863}},coords={x=0.334,y=0.458,source="quest_giver",mapID=863},questType="standard"},
[49079] = {id=49079,name="Hir'eek, the Bat Loa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Hir'eek knows we are here. If my knowledge of Hir'eek is correct, he will personally kill us after we present ourselves. It is time, den. You and I will walk out dere into a horde of blood trolls who want to watch their loa kill us. Take dis dagger. It is coated with de poison I made. I trust you to survive longer than me to use it. You pretend to cower to Hir'eek , and I will do de talking. On my signal, you jump on Hir'eek and start stabbing! ...And den we hope for de best.",starts={{npcID=129378,x=0.334,y=0.458,mapID=863}},ends={{npcID=128276,x=0.312,y=0.468,mapID=863}},coords={x=0.334,y=0.458,source="quest_giver",mapID=863},questType="standard"},
[49080] = {id=49080,name="Cease all Summoning",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I feel something dark and powerful being summoned in de husk of Torga. You need to stop it! Dere must be a summoner using Torga's blood to finish a ritual. Do what you can to stop dem. I will stay here to keep dese tortollans safe from de blood trolls.",starts={{npcID=127961,x=0.584,y=0.138,mapID=863}},ends={{npcID=127961,x=0.584,y=0.138,mapID=863}},coords={x=0.584,y=0.138,source="quest_giver",mapID=863},questType="standard"},
[49081] = {id=49081,name="To Kill a Loa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I am badly hurt... I don't think I can move. Don't worry, I have some potions dat can heal me... slowly. Hir'eek is just down de cavern dere. De poison injured him, but he is a loa, and it will take more than dat to take him down. I can't believe we... YOU are going kill a loa. It's just not someting we do... but Hir'eek serves G'huun. We have no choice! It's all up to you, now. Kill Hir'eek and end dis madness!",starts={{npcID=128276,x=0.312,y=0.468,mapID=863}},ends={{npcID=128276,x=0.312,y=0.468,mapID=863}},coords={x=0.312,y=0.468,source="quest_giver",mapID=863},questType="standard"},
[49082] = {id=49082,name="Upward and Onward",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="It is sad dat Hir'eek had to die, but at least de blood trolls are weaker now. My potions are healing me up nicely. I did some looking around and came across dis guy. He's skittish, but not hostile. I think you can use him to get out of here. Hurry up and jump on, before he breaks de rope! I'll find my own way out; you don't have to worry.",starts={{npcID=128276,x=0.312,y=0.468,mapID=863}},ends={{npcID=122795,x=0.396,y=0.438,mapID=863}},coords={x=0.312,y=0.468,source="quest_giver",mapID=863},questType="standard"},
[49091] = {id=49091,name="Invasion Point: Val",level=45,requiredLevel=45,faction="none",expansion=7,questType="standard"},
[49096] = {id=49096,name="Invasion Point: Naigtal",level=45,requiredLevel=45,faction="none",expansion=7,questType="standard"},
[49097] = {id=49097,name="Invasion Point: Sangua",level=45,requiredLevel=45,faction="none",expansion=7,questType="standard"},
[49098] = {id=49098,name="Invasion Point: Cen'gar",level=45,requiredLevel=45,faction="none",expansion=7,questType="standard"},
[49099] = {id=49099,name="Invasion Point: Bonich",level=45,requiredLevel=45,faction="none",expansion=7,questType="standard"},
[49120] = {id=49120,name="Speaking with the Dead",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Ya be livin' up ta ya part of da bargain. I be ready ta show ya what remains of Torga's soul. I gonna need a little part of ya ta act as a conduit ta be summonin' Torga. Don't worry, I be givin' ya all back. Mostly. After we be done, I be headin' out. Ya always welcome ta call on me again... but only if ya got another deal ready.",starts={{npcID=128096,x=0.566,y=0.266,mapID=863}},ends={{npcID=127961,x=0.584,y=0.138,mapID=863}},coords={x=0.566,y=0.266,source="quest_giver",mapID=863},questType="standard"},
[49122] = {id=49122,name="A Port in Peril",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="A group of mogu have taken hold of Warport Rastari and now threaten to encroach further into my city. It would seem Zul is losing his grip over his pets. Dat port is vital to our military fleet. If de brutes succeed, Zuldazar will fall, and dere won't be a fleet to aid your precious Horde. You wish to prove yourself an ally of de Zandalari? Meet my blade and shield at de port and clean up dis mess.",starts={{npcID=120740,x=0.498,y=0.464,mapID=1165}},ends={{npcID=127815,x=0.478,y=0.604,mapID=862}},coords={x=0.498,y=0.464,source="quest_giver",mapID=862},questType="standard"},
[49123] = {id=49123,name="Killer Crawgs",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="You heard Torga. We need to be taking de fight to de blood trolls if we want to stop dis herald of G'huun. De blood trolls have monstrous crawgs in a camp nearby. We destroy dem, we weaken de blood trolls! De rest of us will move ahead to find out what else de blood trolls have planned around dis place.",questType="standard"},
[49124] = {id=49124,name="Tortollan Rescue",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="If Torga wants us to help you kill the herald of G'huun, then I guess we'll help. First, we need to rescue our people. I found out that the blood trolls are draining the blood of our friends nearby and then feeding them to crawgs! This is no way for a tortollan to die, not after hundred of years gathering stories on Azeroth. Take this scroll. It'll purge whatever blood magic the blood trolls using on my friends. Be careful with my scroll! I want it back in one piece.",questType="standard"},
[49125] = {id=49125,name="Negative Blood",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Okay, you want to kill the herald of a blood god? We can figure something out. There's corrupted blood nearby that's feeding this monster's power. Lucky for you, I've heard stories of this sort of thing before. Take this scroll, but be careful with it! It'll destroy the corrupted blood that's feeding Jungo. Oh, and I need you to find a scroll Holbruk was carrying, called the Scroll of Fate's Hand. It's REALLY powerful. We'll need it.",starts={{npcID=127958,x=0.556,y=0.394,mapID=863}},ends={{npcID=127958,x=0.556,y=0.394,mapID=863}},coords={x=0.556,y=0.394,source="quest_giver",mapID=863},questType="standard"},
[49126] = {id=49126,name="Forcing Fate's Hand",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I got some good news and bad news for you about this whole quest to destroy the herald of G'huun. Bad news first. There's an entire army of skeletons between us and the next area. I'm guessing they used Torga's blood to animate them. Good news is that scroll you recovered from Holbruk can summon the powerful Hand of Fate . ...and the bad news is that the scroll got damaged when Holbruk died and is only good for one more use. Meh. Take this scroll and destroy that skeleton army!",starts={{npcID=127958,x=0.556,y=0.394,mapID=863}},ends={{npcID=127958,x=0.556,y=0.394,mapID=863}},coords={x=0.556,y=0.394,source="quest_giver",mapID=863},questType="standard"},
[49130] = {id=49130,name="Loa-Free Diet",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Princess Talanji thinks we're almost ready to kill this herald of G'huun. Maybe she's right, maybe we're all dead, who knows? What I do know is the blood trolls here are... are carving and carrying away parts of Torga . Ugh! From what I can tell, they're using poor Torga's meat to power their blood rituals. This has to stop! Go out there and steal those pieces of meat from the blood trolls. I'll figure out a way to dispose of it.",starts={{npcID=127958,x=0.556,y=0.394,mapID=863}},ends={{npcID=127958,x=0.556,y=0.394,mapID=863}},coords={x=0.556,y=0.394,source="quest_giver",mapID=863},questType="standard"},
[49131] = {id=49131,name="Sanctifying Ground",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We are so close to weakening dis herald, . Dis is our final push. De nearby area is brimming with blood magic. While you were fighting, I was working on creating totems dat can cleanse de area of blood magic. Take dese totems and place dem nearby. Dey should drain some of de blood magic out of de area. De herald should be weak enough for us to actually kill after all dis.",starts={{npcID=127961,x=0.584,y=0.138,mapID=863}},ends={{npcID=127961,x=0.584,y=0.138,mapID=863}},coords={x=0.584,y=0.138,source="quest_giver",mapID=863},questType="standard"},
[49132] = {id=49132,name="Crushing the Skullcrushers",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Look, , I'll be happy once we've killed this herald and we can have things go back to normal. Until then, you need to deal with these monstrous blood trolls called \"skullcrushers\". Lovely, right? As far as I can tell, these things have some sort of connection to this herald, might be why they're so huge. You kill these skullcrushers and maybe we weaken this herald a bit more. Or maybe it gets even angrier and kills us all. We'll have to see.",starts={{npcID=127960,x=0.584,y=0.138,mapID=863}},ends={{npcID=127960,x=0.584,y=0.138,mapID=863}},coords={x=0.584,y=0.138,source="quest_giver",mapID=863},questType="standard"},
[49136] = {id=49136,name="Jungo, Herald of G'huun",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Dis is it, . De blood magic is weakened enough dat we can actually hurt de herald of G'huun. It is going to take all of us fighting dis thing to stop it. We will meet you inside of Torga. We cannot lose here. If de blood trolls control Torga's blood, den dere will be no way for us to stop dem.",starts={{npcID=127961,x=0.584,y=0.138,mapID=863}},ends={{npcID=127961,x=0.584,y=0.138,mapID=863}},coords={x=0.584,y=0.138,source="quest_giver",mapID=863},questType="standard"},
[49144] = {id=49144,name="Wrath of the Zandalari",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dere is no reasoning with de mogu. Dey only value one thing: strength. Dat is something de Zandalari have like no other, but our forces are spread thin. We are simply not prepared to fight dem. You have proven yourself a capable warrior, for |5 . Would you be our \"ambassador\" to dese brutes? Show dem dat de Zandalari do not stand alone!",starts={{npcID=127815,x=0.478,y=0.604,mapID=862}},ends={{npcID=127815,x=0.478,y=0.604,mapID=862}},coords={x=0.478,y=0.604,source="quest_giver",mapID=862},questType="standard"},
[49145] = {id=49145,name="No Troll Left Behind",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dis is de primary port for de Zandalari fleet. Thankfully most of our ships were out when de mogu came, but Rastari is still an active fortification for de city. De mogu did not land on abandoned shores, . Dere are all manner of brave warriors stationed here, fighting for their lives. Take dis whistle and rally all you can. Our warriors will hear its scream and know dat dey are not alone.",starts={{npcID=127814,x=0.478,y=0.604,mapID=862}},ends={{npcID=127814,x=0.478,y=0.604,mapID=862}},coords={x=0.478,y=0.604,source="quest_giver",mapID=862},questType="standard"},
[49146] = {id=49146,name="Spirits' Belongings",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="You are no Zandalari, but your spirit burns with a passion I have not seen in many years. I am de wavebinder. It is through me dat de loa bless our ships. I will not see my home tainted by dese talking rocks. Gather my bijous, my grimoire, and some of our fallen I set aside for just such an occasion. De brutes think dey have won. Dey will answer to Bwonsamdi soon enough.",starts={{npcID=127837,x=0.496,y=0.644,mapID=862}},ends={{npcID=127837,x=0.496,y=0.644,mapID=862}},coords={x=0.496,y=0.644,source="quest_giver",mapID=862},questType="standard"},
[49147] = {id=49147,name="Show of Strength",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Their leader's time is coming soon now, but we need to dispose of his lieutenants first. Our momentum will be lost if dey reform ranks. Jao-Ti is de first. Legend has it Lei Shen himself said he showed a great connection to de storms. He is leading de mogu's stormbinders. De other is Subjugator Zheng , a slaver dat would make de Kul Tirans blush. You have never seen depravity like his. Kill dem both, and make dem suffer. De mogu are no strangers to war, but neither are we.",starts={{npcID=127814,x=0.478,y=0.604,mapID=862},{npcID=129087,x=0.502,y=0.644,mapID=862},{npcID=129088,x=0.5,y=0.646,mapID=862}},ends={{npcID=127837,x=0.496,y=0.644,mapID=862}},coords={x=0.478,y=0.604,source="quest_giver",mapID=862},questType="standard"},
[49148] = {id=49148,name="Crumbling Apart",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="De mogu army grows with each passing moment thanks to their animated stone warriors. It is only a matter of time before their forces are back at full strength. A thousand curses upon Zul. He was forbidden from bringing his pets here--and from resurrecting de Thunder King in Pandaria. We are de only thing standing between dem and de city. We've got to stop dis while we still can!",starts={{npcID=127815,x=0.478,y=0.604,mapID=862}},ends={{npcID=127837,x=0.496,y=0.644,mapID=862}},coords={x=0.478,y=0.604,source="quest_giver",mapID=862},questType="standard"},
[49149] = {id=49149,name="Embrace the Voodoo",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dese heathens think we are weak. Dey think we are broken. But Zandalari never truly die. I've blessed dat skull Habutu gave you with a bit of voodoo dat will let it break through to de Other Side. You will need to use my spirit obelisks to channel its power. Dey will take it from dere.",starts={{npcID=127837,x=0.496,y=0.644,mapID=862}},ends={{npcID=127837,x=0.496,y=0.644,mapID=862}},coords={x=0.496,y=0.644,source="quest_giver",mapID=862},questType="standard"},
[49160] = {id=49160,name="Torga's Eternal Return",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Well, we did it. Doesn't make the plan we had any less crazy. But there's still one more thing left to do. I've been visiting Torga for years. He told me stories of powerful scrolls, one in particular that he said was meant to be used to put a loa's spirit to rest. I think you should be the one to read it. I mean, if you're SMART enough to read it. Bah! Just take the scroll and read it before I have second thoughts.",starts={{npcID=127960,x=0.584,y=0.138,mapID=863}},ends={{npcID=127958,x=0.556,y=0.394,mapID=863}},coords={x=0.584,y=0.138,source="quest_giver",mapID=863},questType="standard"},
[49185] = {id=49185,name="Catching Up",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Good to see you in one piece, . Nazmir is a place of nightmares, but you seem to be surviving. Rokhan and I convinced your Horde dat we need more support. He is getting ready to meet with reinforcements. We still need to get de loa's aid. What happened with Bwonsamdi and Hir'eek?",starts={{npcID=127961,x=0.584,y=0.138,mapID=863}},ends={{npcID=127961,x=0.584,y=0.138,mapID=863}},coords={x=0.584,y=0.138,source="quest_giver",mapID=863},questType="standard"},
[49190] = {id=49190,name="More Intact Demon Eyes",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=8899,mapID=885,starts={{npcID=128134,x=0.602,y=0.454,mapID=885}},ends={{npcID=128134,x=0.602,y=0.454,mapID=885}},coords={x=0.602,y=0.454,source="quest_giver",mapID=885},questType="standard"},
[49195] = {id=49195,name="Greater Invasion Point: Occularus",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=9298,questType="standard"},
[49196] = {id=49196,name="Greater Invasion Point: Pit Lord Vilemus",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=9296,questType="standard"},
[49197] = {id=49197,name="Greater Invasion Point: Sotanathor",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=9299,questType="standard"},
[49198] = {id=49198,name="Greater Invasion Point: Inquisitor Meto",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=9297,questType="standard"},
[49199] = {id=49199,name="Greater Invasion Point: Matron Folnuna",level=45,requiredLevel=45,faction="none",expansion=7,zoneID=9295,questType="standard"},
[49200] = {id=49200,name="Yet More Intact Demon Eyes",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=8899,mapID=885,starts={{npcID=128134,x=0.602,y=0.454,mapID=885}},ends={{npcID=128134,x=0.602,y=0.454,mapID=885}},coords={x=0.602,y=0.454,source="quest_giver",mapID=885},questType="standard"},
[49278] = {id=49278,name="Spiritual Restoration",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Dis is a sacred place to Bwonsamdi, but now it is little more than a ruin. Even de spirits are unable to escape de passage of time and have faded away, leaving only their drained husks behind. We will return dem to life. Here, I have been collecting de souls from my hunt into dis charm. Use it on de drained spirits , and we will bring dis place back to what it once was.",starts={{npcID=124428,x=0.396,y=0.438,mapID=863}},ends={{npcID=124428,x=0.396,y=0.438,mapID=863}},coords={x=0.396,y=0.438,source="quest_giver",mapID=863},questType="standard"},
[49309] = {id=49309,name="Thunder's Fall",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Warlord Kao commands de mogu from dis warship. It is time to put an end to dis incursion. I should be able to hold off any stragglers dat may come to Kao's aid, but I can only maintain dis barrier for so long. Be careful. Kao was one of de Thunder King's top generals. He will not fall without a fight.",starts={{npcID=127837,x=0.496,y=0.644,mapID=862}},ends={{npcID=127837,x=0.496,y=0.644,mapID=862}},coords={x=0.496,y=0.644,source="quest_giver",mapID=862},questType="standard"},
[49310] = {id=49310,name="The Prophet's Ploy",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="King Rastakhan's life is in grave danger. Zul is far more powerful than he appears. We do not have much time. You have to warn de king before Zul can act. Habutu and Zolani can take you dere. Now go!",starts={{npcID=127837,x=0.496,y=0.644,mapID=862}},coords={x=0.496,y=0.644,source="quest_giver",mapID=1165},questType="standard"},
[49348] = {id=49348,name="A Desecrated Temple",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Da spirits of da faithful flock ta me temple. Ya see dem out dere, yes? Dey come ta enter da Other Side an' join me realm. However, spirits who've turned their backs upon Bwonsamdi , dey too have come to me temple grounds. Dey praise one called \"G'huun,\" and spread their blood magic desecration across da Necropolis. Dis ends now! Go out dere and remove da desecrations dat be infesting me temple.",starts={{npcID=122688,x=0.396,y=0.246,mapID=863}},ends={{npcID=122688,x=0.396,y=0.246,mapID=863}},coords={x=0.396,y=0.246,source="quest_giver",mapID=863},questType="standard"},
[49375] = {id=49375,name="LARRY TEST QUEST",level=1,requiredLevel=1,faction="none",expansion=7,zoneID=8501,mapID=864,questType="standard"},
[49376] = {id=49376,name="Just One Thing",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="You are just in time! Chance be high dat my blood was de next to spill. It is my fault we stopped here. Our team wanted to head back. Crawgs are de trouble, you see. De sanguinous birth of dese young be corrupted by cruel training. They are quite impressionable and dey will follow with just a little enticement. Capture the attention of one of de little squirmy ones nearby. We will see if my theory is correct.",questType="standard"},
[49408] = {id=49408,name="Pirate Dice",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,mapID=895,questType="standard"},
[49421] = {id=49421,name="Hunting Zul",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="Zul is pulling all of his forces back to his stronghold at the Temple of the Prophet. Rastakhan has sent word that he is marshalling an army in the Zocalo with anyone still loyal that can carry a weapon. Looks like the old king had more loyalists than Zul expected. That, and he has three of their eldest loa gathered to his side. Go and lend your strength to their army.",questType="standard"},
[49422] = {id=49422,name="Heretics",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Descend on Zul's fanatics and mogu allies. Hunt them down and slay them all with the fury of a true predator. Show them the true price of their betrayal.",starts={{npcID=129740,x=0.492,y=0.444,mapID=862},{npcID=129740,x=0.392,y=0.276,mapID=1165}},ends={{npcID=129703,x=0.496,y=0.38,mapID=862}},coords={x=0.492,y=0.444,source="quest_giver",mapID=1165},questType="standard"},
[49424] = {id=49424,name="The Full Prophecy",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dat snake of a prophet, Zul. I never trusted him. Always felt like he was never telling us de whole prophecy. Enter de Temple of dis \"Prophet\" and see if he recorded any of his visions. We must learn of what our prey intends, before our real hunt may begin.",starts={{npcID=129561,x=0.492,y=0.444,mapID=862},{npcID=132041,x=0.674,y=0.244,mapID=862}},ends={{npcID=132041,x=0.674,y=0.244,mapID=862}},coords={x=0.492,y=0.444,source="quest_giver",mapID=862},questType="standard"},
[49425] = {id=49425,name="City of Gold",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Rezan and Rastakhan did not wait for us. Dey are marching up de mountain to Atal'Dazar, de City of Gold. You, Loti, and I need to catch up quick and give dem some air support. Hop aboard.",starts={{npcID=129491,x=0.39,y=0.27,mapID=1165},{npcID=129703,x=0.496,y=0.38,mapID=862}},ends={{npcID=131049,x=0.436,y=0.392,mapID=862}},coords={x=0.39,y=0.27,source="quest_giver",mapID=862},questType="standard"},
[49426] = {id=49426,name="The King's Gambit",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Atal'Dazar is the tomb of kings. MY kings. My greatest followers. I will taste Zul's flesh before this day is done. Come, $p, keep up. Our prey has neither the strength nor the numbers to block this entrance. Let us crush this heretic.",starts={{npcID=131049,x=0.436,y=0.392,mapID=862}},ends={{npcID=129757,x=0.426,y=0.376,mapID=862}},coords={x=0.436,y=0.392,source="quest_giver",mapID=1165},questType="standard"},
[49432] = {id=49432,name="The Forlorn Soul",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Where's my ma'da? You seen her? \"I'll be right back,\" she said. I'm a good girl, I wait. I wait and wait, I'm not sure how long I've been waiting here for. It's cold and lonely here. Hey... could you help me find ma'da? I swear I won't cause you any trouble.",starts={{npcID=126588,x=0.426,y=0.314,mapID=863}},ends={{npcID=122688,x=0.396,y=0.246,mapID=863}},coords={x=0.426,y=0.314,source="quest_giver",mapID=863},questType="standard"},
[49440] = {id=49440,name="Blood Troll on the Outside",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="One of our scouts, Jo'chunga, has infiltrated de blood trolls, but we have not heard back from him. I need your help to find Jo'chunga and see what he has discovered about de blood trolls. If you are going to find him, you need to sneak in by looking like one of de blood troll women. Dey are de ones with de most freedom to move around. I have a ritual that can change you. Help me set up de ritual to make you look like a blood troll.",starts={{npcID=122795,x=0.396,y=0.438,mapID=863}},ends={{npcID=122795,x=0.396,y=0.438,mapID=863}},coords={x=0.396,y=0.438,source="quest_giver",mapID=863},questType="standard"},
[49445] = {id=49445,name="The Prime Exchange",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=8899,mapID=885,questType="standard"},
