[49455] = {id=49455,name="Leather - Rank 2 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,questType="standard"},
[49456] = {id=49456,name="Leather - Rank 3 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,questType="standard"},
