[49462] = {id=49462,name="Scales - Rank 3 Unlock",level=10,requiredLevel=10,faction="none",expansion=7,questType="standard"},
[49464] = {id=49464,name="Saurolisk Tails",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,mapID=895,description="Among the upper echelons of Kul Tiran society, there is one cuisine that escapes all but the most determined of chefs. Nobles will pay exorbitant amounts to have just a taste of this delicacy, spiced and cooked to one's delight. I speak, of course, of the saurolisk tail . I must discover the finest method of cooking this sought after comestible! Boiled? Braised? Poached? Perhaps steamed or blanched is the most appropriate method! I will, of course, need a few tails to test.",questType="standard"},
[49472] = {id=49472,name="A Titanic Effort",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,mapID=627,description="Illidan may have forced fate's hand, but bringing Argus so near to Azeroth has accelerated the reaction triggered by the Nightwell's collapse. I believe the Legion's actions on Argus are further destabilizing the powers we've drawn upon unknowingly for many years. It is clear that further studies are required.",questType="standard"},
[49473] = {id=49473,name="A Titanic Effort",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,mapID=627,description="The reaction's intensity is accelerating by the day. We may win the fight against the Legion only to lose something very dear to us. Is this a portent of some greater upheaval to come? What fate awaits our world, ? I will seek answers at my forge, as I have done all my life. Your answers, I suspect, lie elsewhere.",questType="standard"},
[49474] = {id=49474,name="The Cursed Shard",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,mapID=627,description="Someone in Dalaran who works with metals should be able to tell you more.>",questType="standard"},
[49488] = {id=49488,name="Tal'gurub",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="My prophet is a loyal servant, but he has his own ideas of how things must be. I am sending him to Tal'gurub to deal with a mess of his own making. One of his pupils, a witch doctor by de name of Vol'jamba, has taken de Gurubashi enclave as his own and has ousted my guards. Meet Zul at Tal'gurub and ensure dis nuisance is dealt with. Do not let him get... distracted.",starts={{npcID=120740,x=0.498,y=0.464,mapID=1165}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.498,y=0.464,source="quest_giver",mapID=862},questType="standard"},
[49489] = {id=49489,name="Needs a Little Body",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I am here primarily to deal with my wayward student. His followers, however, I will leave to you. I have seen a possible future dat is... concerning. Rivers running red with poison, dead filling de streets. And dese... \"Jambani\" asserting themselves as de new rulers of Zuldazar . Dis cannot come to pass. Fortunately for you, I know how to avoid dat fate. I think you will find their cauldrons are missing one key ingredient. Something to give it a little body, perhaps?",starts={{npcID=129907,x=0.628,y=0.282,mapID=862}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.628,y=0.282,source="quest_giver",mapID=862},questType="standard"},
[49490] = {id=49490,name="The Urn of Voices",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Vol'jamba does possess de Sight, and so even now he is taking precautions against us. Regrettably his vision is incomplete. You will help me prepare for his demise and deal with his followers simultaneously. De tool you will use is called de Urn of Voices. Take it and venture into Tal'gurub. Slay his followers, destroy their golems and masks. Their spirits, once released, will fill de urn. Oh, and try not to die while holding it. De Urn of Voices is not discerning.",starts={{npcID=129907,x=0.628,y=0.282,mapID=862}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.628,y=0.282,source="quest_giver",mapID=862},questType="standard"},
[49491] = {id=49491,name="Fuel for the Voodoo",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Dere be no time! Dey be draining our spirits... using us... dark voodoo... Izita's spirit grows dim, and her voice is soft and distant.> Da totems... burn dem... Den we be free...!",starts={{npcID=130706,x=0.636,y=0.318,mapID=862}},ends={{npcID=278452,x=0.627,y=0.285,mapID=862}},coords={x=0.636,y=0.318,source="quest_giver",mapID=862},questType="standard"},
[49492] = {id=49492,name="Arrogance of Vol'jamba",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Vol'jamba thinks his Sight has surpassed mine. I warned against such arrogance many years ago, but we see how well he listened. No doubt he will attempt to deter us as we encroach upon his sanctum. Listen if you like, but remember dat he is desperate to save himself. His truth is distorted by fear. Destroy his masks and we will walk unharmed through dis passage.",starts={{npcID=129907,x=0.628,y=0.282,mapID=862}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.628,y=0.282,source="quest_giver",mapID=862},questType="standard"},
[49493] = {id=49493,name="Zul's Ethical Dilemma",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Hm. De Gurubashi have earned a reputation for betrayal and weakness. Their activities in Zul'Gurub will be a stain on our records for generations to come. On de other hand... De Zandalari are above de use of slaves. We are strong, capable. De very existence of mindslaves in dis great city is insulting. Dere is a chant dat will free their minds. Use it near de mindslaves to free dem. Or you can simply kill dem. It makes no difference to me.",starts={{npcID=129907,x=0.628,y=0.282,mapID=862}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.628,y=0.282,source="quest_giver",mapID=862},questType="standard"},
[49494] = {id=49494,name="Zuvembi Brew",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Zuvembi brew is arguably a witch doctor's most insidious concoction. Driven by de cauldron master's strength of mind, Zuvembi brew takes de will of those who breathe its fumes. It makes dem compliant, easily manipulated. It is low magic, relying upon ancient cantrips and recipes known only to witch doctors of a certain skill. If we want to eradicate dis brew, we must slay those dat brew it. Find de Zuvembi brewer lurking here and see dat dis knowledge is erased.",starts={{npcID=129907,x=0.628,y=0.282,mapID=862}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.628,y=0.282,source="quest_giver",mapID=862},questType="standard"},
[49495] = {id=49495,name="Enforcing Fate",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Vol'jamba is busy consolidating his power. His Sight has shown him dat he will fight, and perhaps even dat he will die, and so he looks to all his tools to save himself. I will need you to be my hands, as he will come as soon as I show myself. You will undo all de preparations he has made for dis day. Do as I say and we will both find ourselves enjoying de king's favor.",starts={{npcID=129907,x=0.628,y=0.282,mapID=862}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.628,y=0.282,source="quest_giver",mapID=862},questType="standard"},
[49554] = {id=49554,name="Hero's Call: Storm Peaks!",level=25,requiredLevel=25,faction="alliance",expansion=7,zoneID=6611,mapID=501,description="All able-bodied citizens of the Alliance are to report to Rin Duoctane in Dalaran over Crystalsong Forest. The goblins of K3 have built a city in Storm Peaks and have sent their ambassador to recruit adventurers. Speak with Rin and see what the people of K3 need. They would make valuable allies in our fight against the Lich King. Glory to the Alliance!",questType="standard"},
[49569] = {id=49569,name="Down by the Riverside",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We have de aid of Krag'wa and de Gob Squad. We must get back to Zul'jan and begin our plan to stop de blood trolls. We have one problem. De Gob Squad are unable to move their mech fast enough in de jungle. We must take it by boat. De two of us will ride with dem and ensure de blood trolls do not destroy de mech. I will run ahead and get de boat ready near de riverbank. Meet us dere.",starts={{npcID=126213,x=0.674,y=0.422,mapID=863}},ends={{npcID=121288,x=0.392,y=0.79,mapID=863}},coords={x=0.674,y=0.422,source="quest_giver",mapID=863},questType="standard"},
[49590] = {id=49590,name="REUSE ME",level=50,requiredLevel=50,faction="horde",expansion=7,questType="dungeon"},
[49591] = {id=49591,name="REUSE ME",level=0,requiredLevel=0,faction="none",expansion=7,questType="standard"},
