[49598] = {id=49598,name="REUSE ME",level=50,requiredLevel=50,faction="horde",expansion=7,questType="standard"},
[49615] = {id=49615,name="Trust of a King",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="Well, now dat you are settled in, you had best go speak with my father. You can find him up upon de throne, his advisors close at hand, pouring poison in his ear, no doubt. De lift behind you can take you to de Golden Throne above us.",starts={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},ends={{npcID=120740,x=0.498,y=0.464,mapID=1165}},coords={x=0.498,y=0.422,source="quest_giver",mapID=1165},questType="standard"},
[49661] = {id=49661,name="Locally Sourced Eggs",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,mapID=895,description="There is nothing in the world greater than food made from the best, freshest ingredients! My good friend I am on a hunt. A hunt for the perfect eggs! I have heard tale of eel eggs. A delicate texture, a slight undersea saltiness... such a unique flavor profile! I must have them! The eels here lay their eggs on the land before returning to the sea. Please, gather these eggs for me so that I may create only the most elegant of omelets!",questType="standard"},
[49663] = {id=49663,name="False Prophecies",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Now dat dis nuisance is out of de way, I can return my focus to de city. Zuldazar has languished while I was away. You should return to Rastakhan. Let de king know dat his will has been carried out and dat dis false prophet is no more. You might think to share Vol'jamba's prophecy with him, if you feel it worth his notice. I cannot say it will change anything at all.",starts={{npcID=129907,x=0.628,y=0.282,mapID=862}},ends={{npcID=120740,x=0.498,y=0.464,mapID=1165}},coords={x=0.628,y=0.282,source="quest_giver",mapID=1165},questType="standard"},
[49703] = {id=49703,name="House Stormsong",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="I have little information to offer, I'm afraid. I've scarcely left Brennadam as of late. What they said is true. Our militia now enter town only to collect rations rather than guard traders or keep the quilboar at bay. They say they are under orders, but those orders would only come from my brothers at the Shrine. We take oaths to serve our people... it simply does not add up. Brother Addington is nearby at Mariner's Strand. Perhaps he knows more than I.",starts={{npcID=130576,x=0.592,y=0.686,mapID=942}},ends={{npcID=130714,x=0.634,y=0.648,mapID=942}},coords={x=0.592,y=0.686,source="quest_giver",mapID=942},questType="standard"},
[49704] = {id=49704,name="Haywire Harvesters",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="See the golems down there? Farmers use their sharp claws to reap the harvest, but these are cutting timber... Why would they need them here when they have so many laborers on hand? I think the militia is using them to intimidate their own people! See if you can get ahold of an intact mainspring from one. I've helped repair a few back in Boralus. I should be able to figure out who is messing with their innards.",starts={{npcID=130715,x=0.634,y=0.648,mapID=942}},ends={{npcID=130715,x=0.634,y=0.648,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[49705] = {id=49705,name="Unnecessary Duress",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Lord Stormsong has never taken kindly to dissent, but this is madness. These laborers are being worked to death! Addington was a good man. We cannot stand for such cruelty. Take this vial and apply it to the laborers. It contains blessed seawater that will rejuvenate their strength. Avoid engaging what troops you can. They are merely following orders. More death will only worsen matters.",starts={{npcID=130714,x=0.634,y=0.648,mapID=942}},ends={{npcID=130714,x=0.634,y=0.648,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[49706] = {id=49706,name="Proclamation Investigation",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="My lord seldom leaves our holdings along the northern coast, and visitors are expressly forbidden. For most, tidesages like myself are their only connection to the house proper. Lord Stormsong usually delivers orders through proclamations posted throughout the valley. None have reached Brennadam, but if there are any posted here we may be able to find some answers.",starts={{npcID=130714,x=0.634,y=0.648,mapID=942}},ends={{npcID=130714,x=0.634,y=0.648,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[49725] = {id=49725,name="A Risky Ploy",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Things are worse than we thought. These people are about to tear Brennadam apart! We'll never get a chance to talk to Brother Pike in this mess. I have an idea, but if it doesn't work, well... I hope you have your running boots on. Trust me?",starts={{npcID=129999,x=0.592,y=0.694,mapID=942}},ends={{npcID=130576,x=0.592,y=0.686,mapID=942}},coords={x=0.592,y=0.694,source="quest_giver",mapID=942},questType="standard"},
[49738] = {id=49738,name="Hands Off My Booty!",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,mapID=895,description="We are dealing with lawless, no-account thugs. As soon as they gained ground, they started looting! Looting right in the middle of a battle! Well I, for one, am not giving up our booty that easily. Get up to the top of Vigil Hill and man the main cannon. Rain hellfire down on those blaggards! Dismissed!",starts={{npcID=131048,x=0.566,y=0.612,mapID=895}},ends={{npcID=131048,x=0.566,y=0.612,mapID=895}},coords={x=0.566,y=0.612,source="quest_giver",mapID=895},questType="standard"},
[49766] = {id=49766,name="Your Next Move",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,questType="standard"},
[49767] = {id=49767,name="Your Next Move",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="We have some thoughts on the best way to win over the Zandalari. The princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father. General Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here. We should also keep working on winning over the King here in Zuldazar . This city is vast and has many secrets.",questType="standard"},
[49769] = {id=49769,name="Wreckage of the Cataclysm",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=8499,mapID=862,description="In recent years one of the greatest Zandalari loa temples mysteriously fell into the sea. It is a topic of some debate what caused this, and what treasures might have been lost in the catastrophe. My cousin Rokor was in charge of the salvaging efforts. Within the temple were many great items of knowledge and power. I am sure he will have need of the services of someone like yourself with strong arms and working knees.",questType="standard"},
[49777] = {id=49777,name="On The Run",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We were... transporting prisoners when de ambush came... a giant devilsaur... tore through everything. Most of de prisoners escaped in de carnage... dese are hardened criminals. Dey cannot be allowed to roam free! I swore a blood oath dat I would deliver dem to Vol'dun... I am probably going to die here, but I will not die an oathbreaker! Find de escaped criminals and exile dem to Vol'dun.",starts={{npcID=130930,x=0.242,y=0.532,mapID=863}},ends={{npcID=130930,x=0.242,y=0.532,mapID=863}},coords={x=0.242,y=0.532,source="quest_giver",mapID=863},questType="standard"},
[49787] = {id=49787,name="The Ghostlands",level=40,requiredLevel=40,faction="both",expansion=7,zoneID=3433,mapID=95,description="Are you familiar with how the Void elves joined the Alliance? It began with Alleria Windrunner finding out about a blood elf named Umbric. He and his followers were banished from Silvermoon City for researching void magic. Alleria believed she could convince Umbric and his followers to join the Alliance and prevent the void from corrupting them. It all began when she opened up a portal to go into the Ghostlands...",starts={{npcID=126321,x=0.522,y=0.136,mapID=84},{npcID=126332,x=0.522,y=0.136,mapID=84}},coords={x=0.522,y=0.136,source="quest_giver",mapID=95},questType="standard"},
[49789] = {id=49789,name="The Pledge",level=45,requiredLevel=45,faction="none",expansion=7,questType="standard"},
[49791] = {id=49791,name="Lost, Not Forgotten",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="I know not what madness has overtaken my people, but we must stop it together. Take this bell. It calls the souls of the recently deceased to it for later release. We Stormsong do not bury our dead in the earth. The tides claim all. If they will not answer to reason, then we must give them eternal peace. Fallen or not, they are Stormsong.",starts={{npcID=130714,x=0.634,y=0.648,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[49792] = {id=49792,name="Bound and Oppressed",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="We had our orders: ships, and lots of 'em. I led my boys as best I could. Everything changed when the tidesages showed up. We figured they was just checkin' on our progress, but the hood-wearin' bastards turned on us! These anchors bind us here, forcin' us to work to death. No one deserves a fate like that. You gotta free my boys!",starts={{npcID=130904,x=0.646,y=0.622,mapID=942}},ends={{npcID=131248,x=0.664,y=0.564,mapID=942}},coords={x=0.646,y=0.622,source="quest_giver",mapID=942},questType="standard"},
[49793] = {id=49793,name="Means to an End",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="In our haste to journey here I did not think to bring my ritual implements we tidesages use to augment our power. To be honest, I had never expected them necessary on what should have been a peaceful sojourn. Addington does not have his, either. I am sure the militia took him from his home before he had the chance to react. That means his implements should still be in the yard somewhere. We must find them before my power is of much real use.",starts={{npcID=130714,x=0.634,y=0.648,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[49794] = {id=49794,name="The Rising Tide",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="This mainspring wasn't altered by an engineer. These runes on the surface can only have come from a tidesage. Their aquatic magic is unmistakable. I'd bet whoever did this is also responsible for Addington's death. Whoever they are, they're likely still nearby. Keep an eye out... they won't be hard to find.",starts={{npcID=130715,x=0.634,y=0.648,mapID=942}},ends={{npcID=131249,x=0.664,y=0.564,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[49875] = {id=49875,name="First Impressions",level=10,requiredLevel=10,faction="alliance",expansion=7,questType="standard"},
[49880] = {id=49880,name="Blood Bonded",level=10,requiredLevel=10,faction="alliance",expansion=7,questType="standard"},
[49887] = {id=49887,name="Forced Labor",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="H... help... us... Please...",starts={{npcID=130904,x=0.646,y=0.622,mapID=942}},ends={{npcID=130904,x=0.646,y=0.622,mapID=942}},coords={x=0.646,y=0.622,source="quest_giver",mapID=942},questType="standard"},
[49902] = {id=49902,name="To Gloom Hollow",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="There's only one safe area in Nazmir that this Rokhan and your other Horde friends could be in. Gloom Hollow. Lucky for you, it's also close to Krag'wa's den. We used Gloom Hollow as a last stop on our pilgrimage. Make your way to Gloom Hollow along the path I've marked on your map, and tell any tortollans along the way to meet us there. They'll be interested in seeing the end of this story. We'll make our way there and grab anyone else we find.",starts={{npcID=127958,x=0.556,y=0.394,mapID=863}},ends={{npcID=131213,x=0.674,y=0.422,mapID=863}},coords={x=0.556,y=0.394,source="quest_giver",mapID=863},questType="standard"},
[49905] = {id=49905,name="Plot Twist",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="It is time to end Vol'jamba . I want to make one thing clear. He can still kill you. Your fate, moreso than mine, hangs on your ability to fight dis former student of mine. He will bring masks, and voodoo, and he will do everything within his power to end you. All we have done is taken away his ability to cheat. Good luck. For your sake, I hope you do not fail.",starts={{npcID=129907,x=0.628,y=0.282,mapID=862}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.628,y=0.282,source="quest_giver",mapID=862},questType="standard"},
[49932] = {id=49932,name="Slumber No More",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="There's something you should look into. You've got the time anyway, those goblins aren't ready yet. There's a statue nearby. Only, it's not a statue to the trained tortollan eye. It's a deactivated titan keeper ! Noises have been coming from that thing ever since you helped Krag'wa. It must be trying to reactivate itself. I bet that titan-looking amulet of yours could help restart it. We'd be unstoppable against the blood trolls with a titan keeper's help. Go see if you can restart this titan!",starts={{npcID=131978,x=0.674,y=0.42,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.674,y=0.42,source="quest_giver",mapID=863},questType="standard"},
[49935] = {id=49935,name="How to Repair a Titan Keeper",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Major system repair possible within nearby structure. Preliminary goal: repair auxiliary systems. Scans detect three fallen titan keepers. Recover cores. Titan Keeper Hezrel able to retrieve data from cores. Titan Keeper Hezrel goal: reboot auxiliary systems, reach nearby structure, restore all primary systems, seal corruption. Result: corruption contained. Titan Keeper Hezrel able to aid against blood trolls. Blood troll definition not found in databanks.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49937] = {id=49937,name="Recovering Remnants",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Scan of area indicates roaming spirits clad in armor plating. Purpose: defense of structure, animated by corruption. Detecting remnants of titan plating within spirits' armor. Request: recover remnants. Titan Keeper Hezrel capable of breaking down titan plating to reforge into weapon against forces drawn by corruption.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49938] = {id=49938,name="Corrupted Earth",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Unacceptable levels of corruption detected nearby. Scan indicates vegetation affected by corruption. All corruption must be eradicated. Request: destroy any vegetation affected by corruption.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49941] = {id=49941,name="Bone Procession",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Undead entities influenced by corruption surround nearby structure. Impossible to approach. Plan required. Calculating. Plan achieved. Large creatures designated reanimated monstrosities focal gathering point of corruption. Take titan weapon forged from plating recovered. Use it to weaken monstrosities and collect bones. Will run process to destroy bones, prevent creation of further monstrosities.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49949] = {id=49949,name="Unwelcome Undead",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Corruption reanimating dead creatures nearby. Morphing into monstrosities. Must be stopped. Cannot kill all, but can reduce numbers. Reduced numbers equates to less corruption outside of containment. Destroy undead in surrounding area. Keeper Hezrel's systems will continue rebooting while you do so. Reboot goal: recover data regarding nature of corruption.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49950] = {id=49950,name="Blood Purification",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},questType="standard"},
[49952] = {id=49952,name="The Essence of G'huun",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Analysis of blood-infused bones complete. Will be able to create synthetic essence similar to G'huun. Will take a moment to apply essence, allow you to walk past undead without combat. Must hurry. More forces of G'huun are around temple. Must get inside to reactivate containment protocols.",questType="standard"},
[49955] = {id=49955,name="Not Fit for This Plane",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="System restoration in progress. Data recovered. Source of corruption is from an Old God entity. Multiple entities detected nearby, blocking goal of analyzing and containing corruption in Nazmir . Entities appear to be from the Void. Drawn here from Old God corruption. Request to destroy Void entities. Void presence inhibiting repair of systems.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49956] = {id=49956,name="Void is Prohibited",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Scans indicate errors in reality surrounding nearby structure. Portals directly to the Void. Current theory, corruption has Old God as source. Void attracted to Old God corruption. Portals must be sealed to contain entities lured here by Old God corruption. Take this device. Titan Keeper Hezrel has forged it thanks to help in powering up systems. Use device to seal Void portals , prevent more void entities from entering area.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49957] = {id=49957,name="Protocol Recovery",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="System repairs progressing. One key component needed: containment protocol . containment protocol will fully reboot defensive systems. Allow Titan Keeper Hezrel to properly maintain containment. Scans indicate large creature within temple has absorbed slab containing containment protocol . Creature exists between this plane and Void. Request: destruction of creature and retrieval of protocol.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49965] = {id=49965,name="The Warpack",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Zul began a coup, but he did not secure de pyramid for himself. Nor has he done anything to rally more to his banner outside of those who were already conspiring with him. Dis concerns me more than if he had carved his face into Dazar'alor itself. We must learn what he is up to. Join de disciples of Gonk and ride ahead to de Temple of the Prophet. Look to Wardruid Loti for further orders when you arrive.",starts={{npcID=129491,x=0.39,y=0.27,mapID=1165}},ends={{npcID=129740,x=0.392,y=0.276,mapID=1165},{npcID=129740,x=0.492,y=0.444,mapID=862}},coords={x=0.39,y=0.27,source="quest_giver",mapID=862},questType="standard"},
[49975] = {id=49975,name="Rest in the Depths",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="This passage flows through the Shrine of the Storm out into the open sea. We will release the souls of the fallen here. Legends say that as our spirits pass through the Shrine, they aid in the great blessing rituals that all Kul Tiran ships undergo. In that way, we Stormsong never stop serving our people.",starts={{npcID=130714,x=0.634,y=0.648,mapID=942}},ends={{npcID=130714,x=0.634,y=0.648,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[49980] = {id=49980,name="Containment Procedure",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Scans indicate structure has become inoperable. No possibility for repair. Titan Keeper Hezrel 's database fully restored. Believe solution may be within data. Require time to scan data, find solution to contain Old God corruption. Stand by while Titan Keeper Hezrel scans databanks for solution.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=131253,x=0.686,y=0.35,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49985] = {id=49985,name="Return to Gloom Hollow",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Old God G'huun behind destruction of this seal. Commanding blood trolls to destroy final one within Zuldazar. Titan Keeper Hezrel must aid in destruction of blood trolls. Cannot allow Zuldazar seal to be destroyed and G'huun to be freed. Must leave interior of Atul'nazman. Meet Titan Keeper Hezrel outside of temple, will help return to Gloom Hollow. When task is complete, Titan Keeper Herzrel must establish contact with other keeper within G'huun containment chamber.",starts={{npcID=131253,x=0.686,y=0.35,mapID=863}},ends={{npcID=126213,x=0.674,y=0.422,mapID=863}},coords={x=0.686,y=0.35,source="quest_giver",mapID=863},questType="standard"},
[49991] = {id=49991,name="Featherfeet's Fun Falling's Fun Fee!",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,questType="standard"},
[49995] = {id=49995,name="Fabricated Fabrications",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="There was somethin' off with the ship we were building in the yard. I never saw the blueprints, but I've built enough ships in my day to know it wasn't business as usual. They've kept all the pages under tight guard in the Brineworks up the road lately. Full on militia. If you can get your hands on enough of them pages, we oughta be able to figure out what Lord Stormsong and his boys are schemin'.",starts={{npcID=131248,x=0.664,y=0.564,mapID=942}},ends={{npcID=131248,x=0.664,y=0.564,mapID=942}},coords={x=0.664,y=0.564,source="quest_giver",mapID=942},questType="standard"},
[49996] = {id=49996,name="Rearmament",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="The people of this valley have true hearts, . They're eager to take back control of their home. We have to help them. The Brineworks up the road from here supplies most of House Stormsong's weapons. Our movement here could make great use of them. If you can collect enough to go around, I'll go over some basic training with our friends here.",starts={{npcID=131249,x=0.664,y=0.564,mapID=942}},ends={{npcID=131249,x=0.664,y=0.564,mapID=942}},coords={x=0.664,y=0.564,source="quest_giver",mapID=942},questType="standard"},
[49997] = {id=49997,name="Storm's Judgment",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="When I opened my mind to the currents during the ritual, I felt the presence of a member of Lord Stormsong's innermost circle. Wavespeaker Reid. If anyone can locate the missing fleet, it is him. I will not stand by while my brothers move against our own people. Oaths be damned. We must force Reid to see reason.",starts={{npcID=130714,x=0.634,y=0.648,mapID=942}},ends={{npcID=130714,x=0.634,y=0.648,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[49998] = {id=49998,name="Voices Below",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="The others forged ahead to Port Fogtide. I doubt they will receive a warm welcome. We are to meet them there. However, there is something I must do first. Despite Reid's retreat I still feel a terrible darkness nearby; I wish to listen to the tides for answers. I would appreciate your joining me in case more danger strays into our path.",starts={{npcID=130714,x=0.634,y=0.648,mapID=942}},ends={{npcID=134639,x=0.662,y=0.474,mapID=942}},coords={x=0.634,y=0.648,source="quest_giver",mapID=942},questType="standard"},
[50076] = {id=50076,name="Rally the Warriors",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="We have learned so much and came so far thanks to you and de Horde, but all of it will amount to nothing if de blood trolls defeat us here. We've all worked hard since we first set foot within dis accursed swamp, without a chance to even get any sleep or have a decent meal. Dey are some of de finest soldiers I've ever encountered, but even dey have their limits. Let us remind dem what we are fighting for!",starts={{npcID=121288,x=0.392,y=0.79,mapID=863}},ends={{npcID=121288,x=0.392,y=0.79,mapID=863}},coords={x=0.392,y=0.79,source="quest_giver",mapID=863},questType="standard"},
[50078] = {id=50078,name="Undying Totems",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De blood trolls are putting up quite de fight. Dey are raising de very dead to go against us! Their necromancers are raising de dead with de help of totems fueled with blood magic. Destroying dem should take de pressure off our troops.",starts={{npcID=132333,x=0.448,y=0.686,mapID=863}},ends={{npcID=132333,x=0.448,y=0.686,mapID=863}},coords={x=0.448,y=0.686,source="quest_giver",mapID=863},questType="standard"},
[50079] = {id=50079,name="Boom goes the Bomb",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Just look at 'em... those blood trolls are holed up pretty good down there in that fortress of theirs. Multiple defensive lines, lots of equipment, they got everything. They're completely unprepared for us! I almost feel sorry for 'em! Let's start off by showing 'em what we think of their cute attempts at making barricades . Here, take these smoke grenades and put a signal right on top of them. We'll see how well they hold up to high explosives!",starts={{npcID=132988,x=0.448,y=0.684,mapID=863}},ends={{npcID=133125,x=0.452,y=0.604,mapID=863}},coords={x=0.448,y=0.684,source="quest_giver",mapID=863},questType="standard"},
[50081] = {id=50081,name="The Road of Pain",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="My people continue to be captured and hauled into de blood trolls' village for de slaughter, to be used as fuel for their dark rituals. Just ahead, I can see some of de captives who fell along de path. I hear their cries as de blood trolls perform their vile rituals upon dem. We cannot leave my people to die in de swamp, ! Take dese bandages and save any Zandalari you encounter down dere.",starts={{npcID=132333,x=0.448,y=0.686,mapID=863}},ends={{npcID=132333,x=0.448,y=0.686,mapID=863},{npcID=133125,x=0.452,y=0.604,mapID=863}},coords={x=0.448,y=0.686,source="quest_giver",mapID=863},questType="standard"},
[50082] = {id=50082,name="Target of Opportunity",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="It seems our actions here have not gone unnoticed, . I feel a dark presence ahead. Ateena is near! Dis is our chance! If we strike now, we can deal a huge blow to de blood trolls! We must move!",starts={{npcID=133125,x=0.452,y=0.604,mapID=863}},ends={{npcID=133125,x=0.452,y=0.604,mapID=863}},coords={x=0.452,y=0.604,source="quest_giver",mapID=863},questType="standard"},
[50084] = {id=50084,name="Back On Your Feet, Soldier",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="I figured any soldiers we be coming across might be wantin' some revenge, so I brought along some extra weapons just in case. See up ahead? Dem cages be full of trolls awaitin' der turn ta die. We gonna swoop in der and be da answers to der prayers! Go and arm as many of dem as ya can, revenge gonna be sweet!",questType="standard"},
[50087] = {id=50087,name="Ateena's Fall",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="You have proven to be a much greater ally dan I could have ever hoped. Thanks to you and your Horde, we have come dis far. Now, there is only one thing dat remains. We must confront de leader of de blood trolls and put an end to their dark plot once and for all. Without Ateena's mojo to protect it, we can finally destroy dat monstrosity of theirs before it can be unleashed upon Zuldazar. You know what must be done. First, I must prepare myself. Go. I will join you when de battle has begun.",starts={{npcID=133476,x=0.494,y=0.57,mapID=863}},ends={{npcID=133480,x=0.506,y=0.584,mapID=863}},coords={x=0.494,y=0.57,source="quest_giver",mapID=863},questType="standard"},
[50138] = {id=50138,name="The Battle of Bloodfire Ravine",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="It is time to strike out and end de blood troll threat once and for all! We travel back to Bloodfire Ravine, and dis time it is de blood trolls who will be sent running. Mount up, and together we will show dem we are a force to be reckoned with!",starts={{npcID=121288,x=0.392,y=0.79,mapID=863}},ends={{npcID=132333,x=0.448,y=0.686,mapID=863}},coords={x=0.392,y=0.79,source="quest_giver",mapID=863},questType="standard"},
[50139] = {id=50139,name="The Missing Link",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="They are... everywhere... disguised... Encrypted... blueprints... Cipher... Pontus... watching me...",starts={{npcID=280727,x=0.687,y=0.544,mapID=942}},ends={{npcID=131248,x=0.664,y=0.564,mapID=942}},coords={x=0.687,y=0.544,source="quest_giver",mapID=942},questType="standard"},
[50195] = {id=50195,name="Bilgemaul's Brigade",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=8721,mapID=896,description="Drustvar . Taking him out would deal a great blow to the Horde�s war effort, and might just put a halt to these ambushes.>",questType="standard"},
[50235] = {id=50235,name="No Safe Haven",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I brought Rastakhan to Zeb'ahari to hide him, . I did not dream Zul's followers would find us so soon. De people of Zeb'ahari are being hunted by those who answer to de prophet. I have brought dis upon dem by keeping de king in their village. Help me save dem, . Gather those who can still walk and send dem to me. I can do nothing for those who died, but we can still rescue de living.",starts={{npcID=124083,x=0.766,y=0.162,mapID=862}},ends={{npcID=124083,x=0.766,y=0.162,mapID=862}},coords={x=0.766,y=0.162,source="quest_giver",mapID=862},questType="standard"},
[50239] = {id=50239,name="A Choice of Allies",level=40,requiredLevel=40,faction="alliance",expansion=7,zoneID=1519,mapID=84,description="I was chosen to act as an ambassador to our new allies due to my experience with the pandaren joining the Alliance. I've made some notes about some potential allies that may be willing to join the Alliance. Learn more about them, then speak with me.",starts={{npcID=126301,x=0.522,y=0.136,mapID=84},{npcID=126332,x=0.522,y=0.136,mapID=84}},ends={{npcID=126301,x=0.522,y=0.136,mapID=84},{npcID=126332,x=0.522,y=0.136,mapID=84}},coords={x=0.522,y=0.136,source="quest_giver",mapID=84},questType="standard"},
[50250] = {id=50250,name="Posthaste",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=7502,mapID=627,questType="standard"},
[50273] = {id=50273,name="Atal'Dazar: Locking Horns",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=9028,mapID=862,description="We've got tha metal for tha base and tha body, but there's one last part... Tha horn of tha anvil was ta be made of ukrite. But that metal's been gone for ages. There is another metal tha's very close ta it in terms of its durability. A type of gold tha trolls mined in abundance. And I know where ye can find it. Tha trolls control an area called Atal'Dazar, a great city made o' tha stuff. If ye can find something horn-shaped in there, that'll save us tha trouble of shaping it from scratch.",questType="dungeon"},
[50321] = {id=50321,name="Mojo Mischief",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="De soldiers you rescued spoke of de raids on Zandalar. Blood troll raiders, frothing at de mouth and possessing supernatural strength, overwhelmed de defenders. Dey say dat their strength came from flasks of mojo dat de raiders drink before going into combat. We cannot allow de blood trolls to continue to possess them. Go down into de camp and destroy any of their flasks you may find.",questType="standard"},
[50350] = {id=50350,name="We Need a Chemist",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8567,mapID=895,description="All this chaos started when we were picking at a large Azerite node deep in the mine. The mine began to rumble and all of these blasted creatures burst from the ground. If we could just get rid of that vein, I am sure we could retake the mine. First, we need a chemist. The best one we got is in his lab across the river. Find him and he'll give you more instructions.",questType="standard"},
[50354] = {id=50354,name="Look Out!",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9562,mapID=942,description="Some of these quilboar are clearly lookouts. Those horns make it obvious, almost like I could see their task floating above their heads. I was able to kill one, but not before he blew that horn of his and summoned backup. I suggest you keep them silent before they do the same with you. If we're going to get anywhere in there, you'll need to do it quietly. Here, Hobbs gave me a few of his sleeping darts. That should keep them quiet.",starts={{npcID=134752,x=0.586,y=0.704,mapID=942}},ends={{npcID=133953,x=0.466,y=0.738,mapID=942},{npcID=133953,x=0.71,y=0.516,mapID=942}},coords={x=0.586,y=0.704,source="quest_giver",mapID=942},questType="standard"},
[50375] = {id=50375,name="Ride With Me",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I have hunted many powerful foes, $p. My pack has defended this island and its people from countless outside threats and foreign invaders. But there is a darkness growing in Zandalar. A corruption so deep and relentless that it consumes the minds of the Zandalari. I cannot hunt intangible darkness, but I can hunt those who wield it against my people. Come, ride with me and my pack. I smell the foul stench of blood trolls nearby. We will see how well you hunt with the pack.",questType="standard"},
[50420] = {id=50420,name="A Gently Shaken Gift",level=10,requiredLevel=10,faction="none",expansion=7,questType="standard"},
[50432] = {id=50432,name="Titanic Innovation",level=45,requiredLevel=45,faction="both",expansion=7,zoneID=7502,mapID=627,questType="standard"},
[50433] = {id=50433,name="Zanchuli Disbanded",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="I would like to say we are doing well, but we are not. De Zanchuli Council is broken. Raal and I are all dat remain who are still loyal to King Rastakhan. You best bring news to your Horde and tell dem what transpired here. Raal and I will rally what support we can and head for de Zocalo. And hero, thank you for saving my life and my loa.",starts={{npcID=122760,x=0.506,y=0.296,mapID=862}},coords={x=0.506,y=0.296,source="quest_giver",mapID=1165},questType="standard"},
[50520] = {id=50520,name="Where's Sam?",level=30,requiredLevel=30,faction="none",expansion=7,zoneID=9042,mapID=942,questType="standard"},
[50593] = {id=50593,name="A Bloody Mess",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,ends={{npcID=134639,x=0.662,y=0.474,mapID=942}},questType="standard"},
[50594] = {id=50594,name="Beneath the Veil",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="We must board the Abyssal Melody and save the myriad souls in her decks before they too disappear into the Shrine. We will not be able to enter so long as the barrier surrounding it stands. The tidesages are using forbidden magic to summon extensions of their will. It is these grasps that maintain the barrier. Take my beacon and mark each grasp. I will rain vengeance down upon them from here.",starts={{npcID=134639,x=0.662,y=0.474,mapID=942}},ends={{npcID=134639,x=0.662,y=0.474,mapID=942}},coords={x=0.662,y=0.474,source="quest_giver",mapID=942},questType="standard"},
[50595] = {id=50595,name="No Quarter",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="We arrived just in time. These abominations have already taken control of the docks; we're all that's left to keep them at bay! You need to cull their numbers before we're overwhelmed. We don't exactly have an army here!",starts={{npcID=134623,x=0.662,y=0.47,mapID=942}},ends={{npcID=134623,x=0.662,y=0.47,mapID=942}},coords={x=0.662,y=0.47,source="quest_giver",mapID=942},questType="standard"},
[50608] = {id=50608,name="Forbidden Rites",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="These k'thir have been hiding among us, sowing the seeds of their dark masters with us none the wiser. With the barrier around the Abyssal Melody lowered I can peer within; its bowels toil with my own people giving themselves to the shadow! Take my tidal kris ; its blade is now coated in purified tideblood. Put an end to these fiends and their foul rituals.",starts={{npcID=134639,x=0.662,y=0.474,mapID=942}},ends={{npcID=134639,x=0.662,y=0.474,mapID=942}},coords={x=0.662,y=0.474,source="quest_giver",mapID=942},questType="standard"},
[50609] = {id=50609,name="From the Maw of Madness",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Sam is still out there somewhere. We can't just leave him to die! If he wasn't in the assembly yard, he must be on that ship. You have to find him!",starts={{npcID=134623,x=0.662,y=0.47,mapID=942}},ends={{npcID=134641,x=0.66,y=0.472,mapID=942}},coords={x=0.662,y=0.47,source="quest_giver",mapID=942},questType="standard"},
[50610] = {id=50610,name="Gathering Storm",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="This depravity goes against every oath we take as tidesages. To protect our people... to guide and sustain them... to make our ships strong. This is nothing but darkness. It must all be destroyed. Board the Abyssal Melody and place these focusing rods at any critical points you find. I will prepare the ritual.",starts={{npcID=134639,x=0.662,y=0.474,mapID=942}},ends={{npcID=134639,x=0.662,y=0.474,mapID=942}},coords={x=0.662,y=0.474,source="quest_giver",mapID=942},questType="standard"},
[50611] = {id=50611,name="Storm's Vengeance",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="I know not what horrors await us ahead, but the Abyssal Melody must never follow its sister into the Shrine of the Storm. We will deny these monsters all that they have wrought here by burning it with the very magic they seek to corrupt. The ritual is ready, but requires a conduit to stabilize. If you are willing, I would have you guide my magic.",starts={{npcID=134639,x=0.662,y=0.474,mapID=942}},ends={{npcID=134639,x=0.662,y=0.474,mapID=942}},coords={x=0.662,y=0.474,source="quest_giver",mapID=942},questType="standard"},
[50612] = {id=50612,name="A House Divided",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Not all of House Stormsong have followed my Lord down this dark path. They know not - I knew not - the truth of his depravity. Sagehold looms above us. It is where all tidesages study to wield the sea's power. We will build upon the Storm's Wake and make my shattered home whole once more. We will save all who are willing. The rest will perish.",starts={{npcID=134639,x=0.662,y=0.474,mapID=942}},ends={{npcID=135534,x=0.632,y=0.432,mapID=942}},coords={x=0.662,y=0.474,source="quest_giver",mapID=942},questType="standard"},
[50626] = {id=50626,name="LFGDungeons - BFA - Normal Random - 1st",level=10,requiredLevel=10,faction="none",expansion=7,questType="standard"},
[50627] = {id=50627,name="LFGDungeons - BFA - Heroic Random - 1st",level=50,requiredLevel=50,faction="none",expansion=7,questType="standard"},
[50632] = {id=50632,name="Battlefield Scavenging",level=50,requiredLevel=50,faction="horde",expansion=7,description="The battle rages on, but our inventory suffers. Scavenge the camps for supplies. I'll make use of what you find.",questType="group"},
[50694] = {id=50694,name="A Bloody Mess",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="My order blesses every Kul Tiran ship within the halls of the Shrine of the Storm. Our blessings make our ships the strongest in all of Azeroth; the fleet of legend. The ritual requires a substance known as tideblood . It is a viscous, powerful substance dredged from the depths of the sea and infused into the very hull of each ship. Something has caused the tideblood here to become animate. Studying it may help us better understand our enemy.",starts={{npcID=134639,x=0.662,y=0.474,mapID=942}},ends={{npcID=134639,x=0.662,y=0.474,mapID=942}},coords={x=0.662,y=0.474,source="quest_giver",mapID=942},questType="standard"},
[50733] = {id=50733,name="A New Dawn",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="House Stormsong may be lost, but this valley still holds so much hope. Sam knew that from the beginning. We have to continue to help the Storm's Wake in any way we can. There are still remnants of the fallen house everywhere, and whoever turned them to this darkness is out there as well. Cyrus and the others will want to hear about everything that happened. We should tell them together.",starts={{npcID=137692,x=0.782,y=0.288,mapID=942}},ends={{npcID=121235,x=0.68,y=0.22,mapID=1161}},coords={x=0.782,y=0.288,source="quest_giver",mapID=1161},questType="standard"},
[50743] = {id=50743,name="The Immediate Problem",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="I sent one of my lieutenants, a woman by the name of Bauer, to the fishermen's hamlet just down the road. We received a few reports of naga activity spreading down the coast in that direction. We need those forces back as soon as possible. I would ask that you join her in assisting the villagers of the hamlet.",questType="standard"},
[50769] = {id=50769,name="The Stormwind Extraction",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="My lady is shrewd indeed. If we are to infiltrate Stormwind City, we will need the very best the Horde has to offer, and yet a team so small as to be able to infiltrate the heart of Alliance territory unseen. Yes, I see. The path ahead is clear. Speak to me when you are ready to undertake the Warchief's mission, .",starts={{npcID=121210,x=0.58,y=0.628,mapID=862},{npcID=135205,x=0.544,y=0.784,mapID=85}},ends={{npcID=121210,x=0.58,y=0.628,mapID=862}},coords={x=0.58,y=0.628,source="quest_giver",mapID=1165},questType="standard"},
[50777] = {id=50777,name="The Storm Awakens",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="I must watch over Samuel for now. I fear for the darkness assaulting his mind. The fallen men and women around us were defectors from the house. There will be more like them within Sagehold. Find them, and tell them 'the storm awakens'. Knowledge of our cause has spread; we need to bring all we can to our side.",starts={{npcID=135534,x=0.632,y=0.432,mapID=942}},ends={{npcID=136498,x=0.6,y=0.378,mapID=942}},coords={x=0.632,y=0.432,source="quest_giver",mapID=942},questType="standard"},
[50778] = {id=50778,name="Twisted Intentions",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Sails... in the fog... A light below... in the darkness. Water rising... given form... the pain... AHHHH, THE PAIN! Make it stop. Make it stop. Make the pain stop!",starts={{npcID=136053,x=0.632,y=0.432,mapID=942}},ends={{npcID=136498,x=0.6,y=0.378,mapID=942}},coords={x=0.632,y=0.432,source="quest_giver",mapID=942},questType="standard"},
[50780] = {id=50780,name="Oathbound",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="I took oaths, damn it. We all did. When Lord Stormsong sent the first orders... well, you saw what happened. What matters is that our oaths are to our people, not Lord \"Sells His Soul\". You won't find him here - he's deep in the Shrine by now, and no outsider will make it across the channel alive... Not without a Tideguard to open the way. The Rod of Tides is the key to the front door, and it's kept here. Retrieve it and I can get you to him.",starts={{npcID=135517,x=0.608,y=0.412,mapID=942}},ends={{npcID=136497,x=0.618,y=0.362,mapID=942}},coords={x=0.608,y=0.412,source="quest_giver",mapID=942},questType="standard"},
[50781] = {id=50781,name="A Bridge Too Far",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="The bridge that once crossed this span is the only land route to the Shrine. It appears Lord Stormsong has sealed it to buy himself more time. We have been attempting to reopen the way to no avail. However, the Rod of Tides you recovered may prove our solace. Veteran tideguards use it as a key of sorts to maintain the Path of Storms across these dangerous waters. We will begin the ritual once more... if you will wield the rod.",starts={{npcID=136933,x=0.7,y=0.36,mapID=942}},ends={{npcID=136933,x=0.7,y=0.36,mapID=942}},coords={x=0.7,y=0.36,source="quest_giver",mapID=942},questType="standard"},
[50783] = {id=50783,name="The Abyssal Council",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="The tidesages have a leading council beneath Lord Stormsong. They each oversee a different aspect of the order's work. Wavespeaker Reid trains initiates here in the oldest form of tidesage magic: communing with the sea. These deaths are on his hands. It's up to us to take him down.",starts={{npcID=136498,x=0.6,y=0.378,mapID=942}},ends={{npcID=136339,x=0.618,y=0.362,mapID=942}},coords={x=0.6,y=0.378,source="quest_giver",mapID=942},questType="standard"},
[50784] = {id=50784,name="Eye of the Storm",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="If Lord Stormsong wasn't aware of you yet, he is now. Your best shot is to reach him at the Shrine of the Storm before more of his followers fall back to his defense. I can get you in, but you'll have to protect me. I'm in no shape to take down any more of these fiends. And try to keep a low profile. The closer we get to the Shrine, the more power Lord Stormsong has at his disposal.",starts={{npcID=136497,x=0.618,y=0.362,mapID=942}},ends={{npcID=136933,x=0.7,y=0.36,mapID=942}},coords={x=0.618,y=0.362,source="quest_giver",mapID=942},questType="standard"},
[50808] = {id=50808,name="Halting the Empire's Fall",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="Nazmir be havin' problem after problem, . I not be knowin' how it can get much worse dan an Old God tryin' ta take over. I be makin' me way back ta Zul'jan ta lead our efforts ta keep Nazmir safe. Ya should return ta Zuldazar and let Baine know what be goin' on here. Maybe he be likin' dis here underrot, who knows? I can get ya outta here and back ta Zul'jan, if ya be needin' it.",starts={{npcID=137113,x=0.518,y=0.656,mapID=863}},coords={x=0.518,y=0.656,source="quest_giver",mapID=1165},questType="standard"},
[50824] = {id=50824,name="Storm's End",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="I've no doubt he can feel our presence, but so long as Lord Stormsong maintains his spell the first move is ours. We have him surrounded, cornered like the rat he is. We must end this together.",starts={{npcID=137506,x=0.756,y=0.27,mapID=942}},ends={{npcID=137691,x=0.782,y=0.288,mapID=942}},coords={x=0.756,y=0.27,source="quest_giver",mapID=942},questType="standard"},
[50825] = {id=50825,name="Shrine of the Storm: Whispers Below",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9525,mapID=942,description="We must not let Lord Stormsong finish his work. If he delivers the fleet to Azshara, all of Kul Tiras will be vulnerable. Countless innocents will perish -- or worse. There is no time to wait for more of the Storm's Wake to arrive. We finish this now, for the good of all who call this valley home. We finish this for Samuel.",starts={{npcID=137691,x=0.782,y=0.288,mapID=942}},ends={{npcID=137691,x=0.782,y=0.288,mapID=942},{npcID=139970,mapID=942},{npcID=139970,mapID=942}},coords={x=0.782,y=0.288,source="quest_giver",mapID=942},questType="dungeon"},
[50835] = {id=50835,name="The Port of Zandalar",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="King Rastakhan has given me orders to investigate de Harbor of Zandalar. De claim Princess Talanji has levied against General Jakra'zet for failing to maintain de safety of our kingdom is a serious accusation. For dis task, I would have you join me so dat I might have an outside perspective. When you are ready, meet me in de Grand Bazaar.",starts={{npcID=122915,x=0.498,y=0.464,mapID=1165}},ends={{npcID=135441,x=0.5,y=0.85,mapID=1165}},coords={x=0.498,y=0.464,source="quest_giver",mapID=1165},questType="standard"},
[50848] = {id=50848,name="Brgl-Lrgl the Basher",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=8501,mapID=864,questType="standard"},
[50849] = {id=50849,name="Witch Doctor Habra'du",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=8499,mapID=862,questType="standard"},
[50851] = {id=50851,name="Mor'fani the Exile",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=8501,mapID=864,questType="standard"},
[50852] = {id=50852,name="Lady Seirine",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=8499,mapID=862,questType="standard"},
[50881] = {id=50881,name="Royal Report",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8670,mapID=1165,description="Blood magics practiced in de city, guards missing, and our chief spy, Yazma, is acting suspicious. We must present dis to Rastakhan, but without Yazma interfering. Luckily, Rastakhan is a clever king, which is something his opponents often forget. I have prepared a report in a code made by King Rastakhan and known only to myself and my brother, Habutu . Bring it to Habutu and he will see dat it gets to de king's ear.",starts={{npcID=135441,x=0.5,y=0.85,mapID=1165}},ends={{npcID=125953,x=0.5,y=0.464,mapID=1165}},coords={x=0.5,y=0.85,source="quest_giver",mapID=1165},questType="standard"},
[50882] = {id=50882,name="All to Ash",level=10,requiredLevel=10,faction="horde",expansion=7,description="All throughout our campaign here, I understood the warchief's objective. I saw her strategy... believed in its necessity. With Darnassus in Horde hands, the Alliance would be paralyzed. Anger and fear would fester in their hearts until they cracked and splintered like deadwood. But this... this will unite them. They will come for us. All of them. Return to the Undercity, . Speak to the warchief. We must make ready for what is to come.",questType="standard"},
[50963] = {id=50963,name="Of Dark Deeds and Dark Days",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="I should have known better, and now Rezan is dead, and my own power is barely holding on. Soon Bwonsamdi himself will be coming to collect me. Talanji... she must know what has happened here. Go to her, tell her. Aid her where you can. I followed a god of strength and yet I have not de strength to face her with dis shame. For now, I must gather our forces and pursue Zul.",starts={{npcID=129757,x=0.426,y=0.376,mapID=862}},ends={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},coords={x=0.426,y=0.376,source="quest_giver",mapID=1165},questType="standard"},
[51052] = {id=51052,name="Azerite for the Alliance!",level=50,requiredLevel=50,faction="alliance",expansion=7,questType="standard"},
[51059] = {id=51059,name="The Golden Isle",level=30,requiredLevel=30,faction="horde",expansion=7,zoneID=8501,mapID=864,description="Pirate-King Zem'lan don't stay in de port with de rest of us. Too good to crack a jug with his crew no more. We gotta sail out to de Golden Isle to find him. That be de forbidden island where Zem'lan hoards all of de treasure we've pillaged and plundered, so only he can enjoy dem. Hop in my boat and we'll row out dere together.",starts={{npcID=136310,x=0.332,y=0.816,mapID=864}},ends={{npcID=136779,x=0.302,y=0.864,mapID=864}},coords={x=0.332,y=0.816,source="quest_giver",mapID=864},questType="standard"},
[51068] = {id=51068,name="Raiding Their Stores",level=1,requiredLevel=1,faction="horde",expansion=7,zoneID=9439,mapID=14,description="We're low on food supplies. Hit up Newstead and bring us whatever you can find.",ends={{npcID=136321,x=0.596,y=0.256,mapID=14}},questType="group"},
[51070] = {id=51070,name="Raiding the Boulderfist",level=1,requiredLevel=1,faction="horde",expansion=7,zoneID=9439,mapID=14,description="The Boulderfist have recently raided Drywhisker Mine, and are sitting on a large amount of iron ore. We want it back.",ends={{npcID=136321,x=0.596,y=0.256,mapID=14}},questType="group"},
[51086] = {id=51086,name="Break's Over",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9439,mapID=14,description="It's come to my attention a few of our peons have been caught sleeping instead of hauling iron from the mine. We can't let our supplies get low. Take this club and get those lazy peons back on track.",ends={{npcID=131750,x=0.614,y=0.252,mapID=14}},questType="standard"},
[51101] = {id=51101,name="The Wounded King",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="I have things under control here... for now, at any rate. If we want to salvage this situation, Rastakhan must survive. Habutu is gone, but his other guardian, Zolani , has sent word. She is protecting the King at a small fishing village called Zeb'ahari. Find Zolani and do what you can to ensure Rastakhan lives. Be careful, .",ends={{npcID=124083,x=0.766,y=0.162,mapID=862}},questType="standard"},
[51111] = {id=51111,name="King or Prey",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="My loa has seen fit to question my resolve. For my people, my pride, and my faith, we will correct dis. Return to your Horde. Ready your forces, and I will ready mine. When de time comes, we will strike back against de traitorous snake, Zul.",starts={{npcID=124915,x=0.71,y=0.298,mapID=862}},coords={x=0.71,y=0.298,source="quest_giver",mapID=1165},questType="standard"},
[51130] = {id=51130,name="Azerite for the Horde!",level=50,requiredLevel=50,faction="horde",expansion=7,questType="standard"},
[51244] = {id=51244,name="What Rots Beneath",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Good job killin' Ateena and sendin' whatever dat construct was down ta da bottom of... whatever dis ting be. Me scouts be seein' Titan Keeper Hezrel marchin' down to sometin' called da Altar of Rot. Now dat we got rid of dat construct, we can be flyin' down dere ta see what Hezrel be up to. Dis be best handled by you and me. Da princess be havin' business back in da city.",starts={{npcID=140656,x=0.506,y=0.584,mapID=863}},ends={{npcID=137112,x=0.518,y=0.658,mapID=863}},coords={x=0.506,y=0.584,source="quest_giver",mapID=863},questType="standard"},
[51278] = {id=51278,name="Lost and Forgotten",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="We have seen firsthand the depravity that has taken hold of my former brethren. The time has come to put an end to it. The path ahead is no doubt packed with Lord Stormsong's cultists and their soulwrought elementals. I will absorb their souls as they fall with the Dead Ringer, as you once did. However, there will be no release for these fiends... not this time. We will need them to pry open the final door to the Shrine.",starts={{npcID=136933,x=0.7,y=0.36,mapID=942}},coords={x=0.7,y=0.36,source="quest_giver",mapID=942},questType="standard"},
[51305] = {id=51305,name="Jelly Clouds",level=26,requiredLevel=26,faction="none",expansion=7,zoneID=8499,mapID=862,questType="world"},
[51312] = {id=51312,name="Aromatic Pollenator",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="While gathering the pollen, you found a dead bug absolutely covered in pollen. You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp. Maybe if you ask Declan about it, he might have an idea.",ends={{npcID=136096,x=0.704,y=0.06,mapID=1161}},questType="standard"},
[51319] = {id=51319,name="The Final Ascent",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Beyond this gate lies Lord Stormsong... and our retribution. It seems he has sealed it tight, likely to buy himself time to finish whatever foul ritual awaits us. Release the souls within the Dead Ringer when you are ready. I will direct them into the binding holding the gate shut. From there, we find Stormsong and end this once and for all.",starts={{npcID=137506,x=0.756,y=0.27,mapID=942}},ends={{npcID=137506,x=0.756,y=0.27,mapID=942}},coords={x=0.756,y=0.27,source="quest_giver",mapID=942},questType="standard"},
[51320] = {id=51320,name="Sealed Fate",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Three wards ahead threaten to block our entry into the Shrine. We call them the Tidemother's Wrath , Radiance, and Pride. Legends say the wards were gifts from the sea itself. They once protected our flagships against even the fiercest storms. Ever since we settled here they have instead kept the Shrine of the Storm safe. It seems Lord Stormsong has turned their power against us. I can feel their energy radiating out even from here, protecting his forces from our magic. We must destroy them.",starts={{npcID=136933,x=0.7,y=0.36,mapID=942}},coords={x=0.7,y=0.36,source="quest_giver",mapID=942},questType="standard"},
[51335] = {id=51335,name="Cookies and Cream",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Thank you for helping me collect everything. I couldn't let you go out there and battle those mean ettins on an empty stomach. Now, I would be no better than those terrible monsters if I did that, would I? $p, you just feel free to take a load off while I make you a fresh batch of cookies and some warm milk!",starts={{npcID=136658,x=0.304,y=0.668,mapID=942}},ends={{npcID=136658,x=0.304,y=0.668,mapID=942}},coords={x=0.304,y=0.668,source="quest_giver",mapID=942},questType="standard"},
[51342] = {id=51342,name="Battle for Stromgarde",level=50,requiredLevel=50,faction="none",expansion=7,questType="standard"},
[51344] = {id=51344,name="To Matters at Hand",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="Ye need te get back te Zuldazar, Princess Talanji 's people are in desperate need of help. Now that ye got the heart, ye can absorb Azerite from all kinds of sources. Use the teleporter pad behind ye te return te Zuldazar. I be disablin' it when yer done... no need te have the likes of Nathanos walkin' in here. Just remember. Ye got the Heart of Azeroth around yer neck. Whatever happens... we must save the planet.",starts={{npcID=136907,x=0.5,y=0.616,mapID=84}},ends={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},coords={x=0.5,y=0.616,source="quest_giver",mapID=1165},questType="standard"},
[51360] = {id=51360,name="Enormous Anchor Pod",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it. Your mind wanders back to Declan, and if there is anything about it in the book you picked up earlier.",ends={{npcID=136096,x=0.704,y=0.06,mapID=1161}},questType="standard"},
[51370] = {id=51370,name="Short-Supply Reward",level=50,requiredLevel=50,faction="none",expansion=7,questType="standard"},
[51401] = {id=51401,name="Carry On",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Let's get to Brennadam right away. We need to find Brother Pike and get to the bottom of all of this before things get any worse. This road should take us right into town. Brennadam's the busiest market this side of Boralus, so there should be plenty of people there who can help us find Pike. Ready when you are!",starts={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},ends={{npcID=129999,x=0.592,y=0.694,mapID=942}},coords={x=0.652,y=0.686,source="quest_giver",mapID=942},questType="standard"},
[51404] = {id=51404,name="What Happens Next",level=10,requiredLevel=10,faction="none",expansion=7,description="After feeling the bite of Akunda so many times, static electricity causes your hair to stand on end as you hold in your hands an intact lightning pod. You noticed that by wrapping the lightning pod in it's own leaves, you were able to remove it without discharging it. If you manage to develop this technique, harvesting this plant would become significantly less hazardous and provide additional material in pristine condition.",questType="standard"},
[51425] = {id=51425,name="There's No Place Like Home",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9734,description="So, the Arathi Highlands. Quite a sprawl, isn't it? At some point, you may wish to return to this fair Stromgarde with haste. Might I offer a suggestion as to how...?",ends={{npcID=137698,x=0.48,y=0.798,zoneID=9734}},questType="standard"},
[51443] = {id=51443,name="Battle for Azeroth: Mission Statement",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="! The Warchief has summoned you to undertake a mission of the utmost secrecy. The very future of the Horde is at stake.",starts={{npcID=49750,x=0.658,y=0.496,mapID=90},{npcID=49750,x=0.494,y=0.768,mapID=85},{npcID=140176,x=0.49,y=0.916,mapID=85},{npcID=49750,x=0.426,y=0.582,mapID=88},{npcID=121210,x=0.58,y=0.628,mapID=862}},ends={{npcID=135205,x=0.544,y=0.784,mapID=85}},coords={x=0.658,y=0.496,source="quest_giver",mapID=862},questType="standard"},
[51487] = {id=51487,name="Searching for Answers",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="There's a saying Cyrus always said when I was a kid: \"The best face is a friendly one.\" It's really helped me get to know the visitors from all over the world that come through Boralus. Let's ask some of the people in charge around here and see if they know anything about the fleet. Maybe it's just a matter of asking nicely!",starts={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},coords={x=0.652,y=0.686,source="quest_giver",mapID=942},questType="standard"},
[51488] = {id=51488,name="Archived Knowledge",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=8567,mapID=895,description="It seems like this Brother Alen we keep hearing about might have some answers. At least, I sure hope so. Everyone here seems a bit... evasive. I think I saw some archivists heading into the southern cloister. If we follow them, I bet we'll find Alen too.",starts={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},coords={x=0.652,y=0.686,source="quest_giver",mapID=895},questType="standard"},
[51489] = {id=51489,name="Time to Leave",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="I knew it! I knew the fleet wasn't just lost! We may be a little in over our heads here. Let's leave before things get out of hand. Galeheart can take us to Stormsong Valley from here. No point in following tradition at this point, right?",starts={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},ends={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},coords={x=0.652,y=0.686,source="quest_giver",mapID=942},questType="standard"},
[51490] = {id=51490,name="Border Issues",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="They've closed off the entire valley! No wonder so many people have been complaining about trading with the Brennadam market. We have to do something about this. These people need to make a living! You're going to have to be an honorary cadet for me here, . Tell these ruffians to clear the road!",starts={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},ends={{npcID=137866,x=0.652,y=0.686,mapID=1161},{npcID=137866,x=0.578,y=0.858,mapID=942}},coords={x=0.652,y=0.686,source="quest_giver",mapID=942},questType="standard"},
[51535] = {id=51535,name="A Veteran's Summons",level=40,requiredLevel=40,faction="horde",expansion=7,description=", we received word from Orgrimmar. Eitrigg has requested a meeting. Says it's important. He left a letter for you. I wouldn't keep him waiting or he might expire of old age before you find out what he wants.",questType="standard"},
[51557] = {id=51557,name="Irontide Warning",level=30,requiredLevel=30,faction="alliance",expansion=7,zoneID=9042,mapID=942,description="Horde's taking this town! I'm not gonna stick around to watch! You could help me out though. Go see Leo Shealds in Deadwash. Tell him, Irontide is still coming and we're taking the gold!",questType="standard"},
[51593] = {id=51593,name="Bridgeport Investigation",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,mapID=895,description="While you're in Bridgeport, you might keep an ear out for any information that will be of aid to us. You'd be surprised what you can learn by staying quiet and listening to people who think they're alone...",starts={{npcID=138287,x=0.72,y=0.518,mapID=895}},ends={{npcID=138287,x=0.72,y=0.518,mapID=895}},coords={x=0.72,y=0.518,source="quest_giver",mapID=895},questType="standard"},
[51663] = {id=51663,name="Preparing for the Fall",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,starts={{npcID=290750,x=0.653,y=0.283,mapID=862}},ends={{npcID=129907,x=0.628,y=0.282,mapID=862}},coords={x=0.653,y=0.283,source="quest_giver",mapID=862},questType="standard"},
[51677] = {id=51677,name="Mending Body and Soul",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Good. You have brought me the last ingredients I will need to concoct a solution to close the king's wounds. You are not a moment too soon. He is fading. I am not comfortable working at an elevated pace, but the situation requires it. You must be my hands, for I am very slow. Bring me what I need, and let Jamil and I worry about the rest. Speak to me when you are ready to begin.",starts={{npcID=124063,x=0.764,y=0.16,mapID=862}},ends={{npcID=124063,x=0.764,y=0.16,mapID=862}},coords={x=0.764,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[51678] = {id=51678,name="Rastakhan's Might",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Do you see de ship out in de bay, ? Dat is my flagship, Rastakhan's Might. It is not here under my orders. We will deal with de Prophet Zul in good time. For now, those who took my vessel must pay. You are to bring me de head of Windcaller Ula'jan. De ship does not move without him, and it will not be moving again once he is dead!",starts={{npcID=124062,x=0.766,y=0.16,mapID=862}},ends={{npcID=124062,x=0.766,y=0.16,mapID=862}},coords={x=0.766,y=0.16,source="quest_giver",mapID=862},questType="standard"},
[51679] = {id=51679,name="A Strange Port of Call",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9772,description="I know Rastakhan is furious dat dey claimed his ship, of all de vessels in our navy. But dere is a better question to ask. Why did dey bring it here? Zeb'ahari is a small fishing village. Dere are no warriors here, no powerful supporters of de king. Dere must be another reason. Board de ship and have a good look around. See if you can find out why dey brought dat beast of a boat way out here.",starts={{npcID=124083,x=0.766,y=0.162,mapID=862}},ends={{npcID=124062,x=0.766,y=0.16,mapID=862}},coords={x=0.766,y=0.162,source="quest_giver",zoneID=8499},questType="standard"},
[51680] = {id=51680,name="In Bwonsamdi's Shadow",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=8499,mapID=862,description="Something is wrong, . My king is blessed by de loa in ways your kind cannot imagine. He has been given long life, swift healing, and strength beyond most trolls. But still, he lingers on death's door. I can practically hear Bwonsamdi laughing. Two of his most trusted menders are with him. Go and find out what is taking so long. I will make sure dey are not interrupted.",starts={{npcID=124083,x=0.766,y=0.162,mapID=862}},ends={{npcID=124063,x=0.764,y=0.16,mapID=862}},coords={x=0.766,y=0.162,source="quest_giver",mapID=862},questType="standard"},
[51753] = {id=51753,name="Champion: Rexxar",level=35,requiredLevel=35,faction="horde",expansion=7,zoneID=9042,mapID=942,starts={{npcID=138876,x=0.52,y=0.336,mapID=942}},ends={{npcID=138876,x=0.52,y=0.336,mapID=942}},coords={x=0.52,y=0.336,source="quest_giver",mapID=942},questType="standard"},
[51818] = {id=51818,name="Commander and Captain",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9042,mapID=942,description="This brings me no joy, , but I will do what I must to make sure my family is happy and safe. I would prefer we avoid violence, but if we must... there are two targets. Their leaders. Captain Malia and Commander Augustine. Their loss should force the two groups to retreat from the area. Also, Augustine confiscated a book of mine. Recover it and my powers are yours, for however long I have left.",starts={{npcID=139098,x=0.626,y=0.318,mapID=942}},ends={{npcID=139098,x=0.626,y=0.318,mapID=942}},coords={x=0.626,y=0.318,source="quest_giver",mapID=942},questType="standard"},
[51926] = {id=51926,name="Pristine Akun'Jar Vase",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=9598,mapID=1165,description="This artifact has been restored to a remarkably excellent condition, suitable for display in your new ally's capital city.",questType="standard"},
