[52008] = {id=52008,name="Champion: Magister Umbric",level=35,requiredLevel=35,faction="alliance",expansion=7,zoneID=8501,mapID=864,starts={{npcID=139568,x=0.374,y=0.358,mapID=864}},ends={{npcID=139568,x=0.374,y=0.358,mapID=864}},coords={x=0.374,y=0.358,source="quest_giver",mapID=864},questType="standard"},
[52013] = {id=52013,name="Champion: John J. Keeshan",level=35,requiredLevel=35,faction="alliance",expansion=7,zoneID=8500,mapID=863,starts={{npcID=139609,x=0.618,y=0.412,mapID=863}},ends={{npcID=139609,x=0.618,y=0.412,mapID=863}},coords={x=0.618,y=0.412,source="quest_giver",mapID=863},questType="standard"},
[52044] = {id=52044,name="An Exceptional Platinum Shard",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks. You wonder to yourself if Myra could teach you to harvest this much every time.",ends={{npcID=136091,x=0.75,y=0.076,mapID=1161}},questType="standard"},
[52051] = {id=52051,name="LFGDungeons - BFA - Raid Finder - 1st",level=50,requiredLevel=50,faction="none",expansion=7,questType="standard"},
[52061] = {id=52061,name="Taptaf the Pig!",level=50,requiredLevel=50,faction="both",expansion=7,zoneID=8721,mapID=896,starts={{npcID=139380,x=0.65,y=0.832,mapID=896}},ends={{npcID=139380,x=0.65,y=0.832,mapID=896}},coords={x=0.65,y=0.832,source="quest_giver",mapID=896},questType="standard"},
[52073] = {id=52073,name="Petitioning Krag'wa",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Nothing! I cannot believe de weapon had no effect! Damn Ateena and her dark magic! We must get up there somehow, kill her for good, and remove dat barrier! But how can we get to de top of dat building... ah, of course! Krag'wa! De loa of frogs hates de blood trolls. I am sure he will lend us his aid. Then, finally, we will be able to put an end to Ateena's madness.",starts={{npcID=133125,x=0.452,y=0.604,mapID=863}},ends={{npcID=133476,x=0.494,y=0.57,mapID=863}},coords={x=0.452,y=0.604,source="quest_giver",mapID=863},questType="standard"},
[52149] = {id=52149,name="Everburning",level=20,requiredLevel=20,faction="alliance",expansion=7,zoneID=8721,mapID=896,description="My people have suffered loss and pain, struggling in the darkness that covered Drustvar . But now we have some light back. We have the means and the will to reclaim our lands from the lingering evils. Your help has brought much of that about. I will miss my parents. Though their end was dark, they were family. But my duty as the head of House Waycrest is clear. The dead can handle themselves. I must attend to the living and lead. There is a short ceremony I need to conduct. Would you assist me?",starts={{npcID=129642,x=0.368,y=0.5,mapID=896},{npcID=142651,x=0.36,y=0.512,mapID=896}},ends={{npcID=142651,x=0.36,y=0.512,mapID=896}},coords={x=0.368,y=0.5,source="quest_giver",mapID=896},questType="standard"},
[52154] = {id=52154,name="Our Next Target",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="Welcome back, $p. We're ready to set sail on our next mission.... Now we just need to reach an agreement on where we're headed. General Feathermoon and I disagree on which Horde target we should prioritize next. But if you'll give me just a moment, I'm confident I can convince her the value of my strategy and we'll be swiftly on our way. I've considered every reasonable alternative. This is the best course of action.",starts={{npcID=135612,x=0.694,y=0.27,mapID=1161}},ends={{npcID=135612,x=0.694,y=0.27,mapID=1161}},coords={x=0.694,y=0.27,source="quest_giver",mapID=1161},questType="standard"},
[52212] = {id=52212,name="Battle for Stromgarde",level=50,requiredLevel=50,faction="none",expansion=7,questType="standard"},
[52224] = {id=52224,name="Ivory Handled Dagger",level=10,requiredLevel=10,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="While skinning the beast, you feel a lump within the beast's stomach. Investigating further, you find what appears to be a dagger with a beautifully etched ivory handle. Carefully extracting it, you wonder if Camilla Darksky might know something about this.",ends={{npcID=136061,x=0.758,y=0.132,mapID=1161}},questType="standard"},
[52294] = {id=52294,name="Fallen Idols",level=20,requiredLevel=20,faction="horde",expansion=7,zoneID=8500,mapID=863,description="Little creature, please... listen to me. I am Krag'wa. Once, my worshipers were many and my powers great. Now, my followers are all but gone. What little power I have left was placed within several idols, but the idols have been stolen by the heretical blood trolls. I ask you, please recover my idols so that I can become whole once more!",starts={{npcID=120551,x=0.754,y=0.566,mapID=863}},ends={{npcID=120551,x=0.754,y=0.566,mapID=863}},coords={x=0.754,y=0.566,source="quest_giver",mapID=863},questType="standard"},
[52439] = {id=52439,name="Iron Stores",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9734,description="While the mine is under Alliance banners our workers ensure the iron supply never runs dry. This key will provide access to the stores. Take what you need.",starts={{npcID=139942,x=0.61,y=0.672,zoneID=9734},{npcID=141145,x=0.472,y=0.742,zoneID=9734}},ends={{npcID=141145,x=0.472,y=0.742,zoneID=9734}},coords={x=0.61,y=0.672,source="quest_giver",zoneID=9734},questType="standard"},
[52440] = {id=52440,name="Resource Recruitment",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9734,description="If we're to maintain our iron supply we'll need a bit of help. See if you can wrangle us up a few fresh recruits for the mine.",ends={{npcID=141145,x=0.472,y=0.742,zoneID=9734}},questType="standard"},
[52450] = {id=52450,name="Uniting Kul Tiras",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,mapID=1161,starts={{npcID=135612,x=0.694,y=0.27,mapID=1161}},ends={{npcID=135612,x=0.694,y=0.27,mapID=1161}},coords={x=0.694,y=0.27,source="quest_giver",mapID=1161},questType="standard"},
[52451] = {id=52451,name="Uniting Zandalar",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8499,mapID=862,starts={{npcID=135691,x=0.584,y=0.626,mapID=862}},ends={{npcID=135691,x=0.584,y=0.626,mapID=862}},coords={x=0.584,y=0.626,source="quest_giver",mapID=862},questType="standard"},
[52467] = {id=52467,name="Battlefield Scavenging",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=9734,description="Our efforts to reclaim the keep have left our supplies a bit lighter than we anticipated. If our forces are to continue, we'll need to restock. Check the enemy camps for anything of value. We'll make use of what you find.",ends={{npcID=141276,x=0.484,y=0.752,zoneID=9734}},questType="group"},
[52468] = {id=52468,name="Raiding Their Stores",level=50,requiredLevel=50,faction="alliance",expansion=7,description="Our rations are low. We need to keep our forces fed if we're to continue our efforts. Before it was overrun, Newstead had plenty of food in their stores. I only hope there's something left.",questType="group"},
[52497] = {id=52497,name="Raiding the Boulderfist",level=50,requiredLevel=50,faction="alliance",expansion=7,description="The Boulderfist have been rather active ever since the battle began. One of our scouts reported their recent raid on Galson's Lode proved rather lucrative. Scout the cave to the northeast, find the iron ore they stole and steal it back. We can't afford to let anyone else control our resources.",questType="group"},
