[52788] = {id=52788,name="Leave None Alive",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8499,mapID=862,description="Our initial assault was a success. The Dark Iron dwarves are holding the line. Now it's our turn. You and I must cleave a path through these Zandalari and eliminate them. Our forces will handle any that remain. Our goal is to weaken their forces and find two important targets: the ship's captain and its advisor. Let's go, . If we fail here, all of our efforts will be thwarted.",starts={{npcID=141719,x=0.35,y=0.772,mapID=862}},coords={x=0.35,y=0.772,source="quest_giver",mapID=862},questType="standard"},
