[52970] = {id=52970,name="No Small Mercy",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=148,mapID=62,description="I will not slay innocents. If they do not raise arms against us, we shall spare them. Enter Lor'danel and capture any civilians you find there. They shall be questioned and then released.",starts={{npcID=142310,x=0.522,y=0.224,mapID=62}},ends={{npcID=142310,x=0.522,y=0.224,mapID=62}},coords={x=0.522,y=0.224,source="quest_giver",mapID=62},questType="standard"},
