[53550] = {id=53550,name="A Change in Leadership",level=10,requiredLevel=10,faction="horde",expansion=7,description="In my experience people do not like to be driven from their homes. While normally we would crush them with the might of the Horde, we do not have time to carry out a lengthy campaign against these creatures. They will look to their leaders for hope, inspiration, and guidance. They will find none. You are the instrument of my will, . Make them submit to it.",questType="standard"},
