[53667] = {id=53667,name="Welcome to the Workshop",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9439,mapID=14,description="You must be the new around here. Name's Margie. And that over there, that's Pixy. We run a tight crew here at the workshop. So, if you ever need anything, you know where to find us. Now, I suggest you head on over and check in with Pixy. She can show you what we have to offer.",starts={{npcID=134855,x=0.584,y=0.216,mapID=14}},ends={{npcID=134855,x=0.584,y=0.216,mapID=14}},coords={x=0.584,y=0.216,source="quest_giver",mapID=14},questType="standard"},
[53668] = {id=53668,name="Flightgineer's Network",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9439,mapID=14,description="Now that we control High Perch the skies are ours! I've laid out a few plans for expanding our routes in this here note. If you'd be so kind as to deliver it to our commander, I'm sure they'll be pleased with our progress. Let me know when you're ready and l'll send ya on your way.",starts={{npcID=127068,x=0.512,y=0.472,mapID=14}},ends={{npcID=126472,x=0.616,y=0.26,mapID=14},{npcID=131465,x=0.616,y=0.26,mapID=14},{npcID=136202,x=0.616,y=0.26,mapID=14}},coords={x=0.512,y=0.472,source="quest_giver",mapID=14},questType="standard"},
[53670] = {id=53670,name="Beasts of Newstead",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9439,mapID=14,description="Nothing penetrates an enemy's front line like a fierce rider and a well-trained beast. Now that we control Newstead, one of our riders in particular has focused his efforts on training us a few kodos. Go, check in with Tanauk and find out what these beasts are capable of.",starts={{npcID=132349,x=0.426,y=0.416,mapID=14}},ends={{npcID=132349,x=0.426,y=0.416,mapID=14}},coords={x=0.426,y=0.416,source="quest_giver",mapID=14},questType="standard"},
[53675] = {id=53675,name="Welcome to the Workshop",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9734,description="Welcome to the workshop! I told Grumble I thought it best for me ta protect him from unnecessary distractions, but I think it may benefit all of us if ye get a peek at what we're doin' 'round here. Why don't ye head on over and see what we have ta offer.",starts={{npcID=139106,x=0.506,y=0.722,zoneID=9734}},ends={{npcID=139106,x=0.506,y=0.722,zoneID=9734}},coords={x=0.506,y=0.722,source="quest_giver",zoneID=9734},questType="standard"},
[53676] = {id=53676,name="The Circle's Power",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9734,description="The Circle of Elements presents us with an opportunity to harness great power. One of our allies, Justine, has great knowledge into what this might mean for our efforts. Seek her out. It's time you discovered the power of the elements.",starts={{npcID=144613,x=0.696,y=0.476,zoneID=9734}},ends={{npcID=144613,x=0.696,y=0.476,zoneID=9734}},coords={x=0.696,y=0.476,source="quest_giver",zoneID=9734},questType="standard"},
[53677] = {id=53677,name="Beasts of Newstead",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9734,description="Control of Newstead has allowed our forces to advance. It's also provided Vindicator Banra ample room to continue training his elekk for battle. I suggest you speak with him to learn more about what these magnificent beasts are capable of.",starts={{npcID=139478,x=0.424,y=0.408,zoneID=9734}},ends={{npcID=139478,x=0.424,y=0.408,zoneID=9734}},coords={x=0.424,y=0.408,source="quest_giver",zoneID=9734},questType="standard"},
[53678] = {id=53678,name="Establishing a Connection",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=9734,description="Now that we control High Perch the skies are ours! I've drafted plans for a flight network that provides our allies safe passage. Please, take these notes and deliver them to our commander at once. I'm happy to provide you with a gryphon that will deliver you to the base when you are ready.",starts={{npcID=132005,x=0.522,y=0.46,mapID=14},{npcID=132005,x=0.512,y=0.472,zoneID=9734}},ends={{npcID=137699,x=0.476,y=0.754,zoneID=9734},{npcID=137700,x=0.476,y=0.754,zoneID=9734},{npcID=137701,x=0.476,y=0.754,zoneID=9734}},coords={x=0.522,y=0.46,source="quest_giver",zoneID=9439},questType="standard"},
