[53766] = {id=53766,name="His Eye Upon You",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="Dark mojo has fallen upon you, . I can sense de tendrils of N'Zoth delving deep into your mind. Dis evil must be purged... before it claims your very soul! Go to de Altar of Akunda in de Terrace of de Chosen. Seek out Nailok , one of de priests of Akunda. He is your best chance to be cleansed of de wicked curse dat grips you.",starts={{npcID=133050,x=0.498,y=0.422,mapID=1165},{npcID=146335,x=0.498,y=0.464,mapID=1165},{npcID=133050,x=0.396,y=0.692,mapID=1165}},ends={{npcID=146776,x=0.454,y=0.14,mapID=1165}},coords={x=0.498,y=0.422,source="quest_giver",mapID=1165},questType="standard"},
[53787] = {id=53787,name="Modular Construction",level=50,requiredLevel=50,faction="none",expansion=7,description="The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen! You look like the adventurous type, . Can you go scrap up some mechs? Don't forget your Arclight Spanner!",questType="standard"},
[53800] = {id=53800,name="Battle for Darkshore",level=50,requiredLevel=50,faction="alliance",expansion=7,questType="standard"},
[53801] = {id=53801,name="Battle for Darkshore",level=50,requiredLevel=50,faction="horde",expansion=7,questType="standard"},
[53926] = {id=53926,name="Cause for Concern",level=80,requiredLevel=80,faction="horde",expansion=7,zoneID=6298,mapID=109,description="Shadowmaster Skrizzik's behavior was unusual. His repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation. You should report back to Stone Guard Mollivox .",questType="standard"},
[53943] = {id=53943,name="Modular Construction",level=50,requiredLevel=50,faction="alliance",expansion=7,description="The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen! You look like the adventurous type, . Can you go scrap up some mechs? Don't forget your Arclight Spanner!",questType="standard"},
[53953] = {id=53953,name="Brawl'gar Awaits!",level=80,requiredLevel=80,faction="horde",expansion=7,zoneID=6298,mapID=109,description="Tired of standing around in the boring old Valley of Strength? Come on over to the Brawl'gar Arena, and fight for the amusement of others! You might win, or you might get killed, but either way, you're going to have a great time. Grab an invitation and bring it to Skuglor , near the front door. Brawl'gar awaits!",questType="standard"},
[54004] = {id=54004,name="Test Case #1; Mech vs. Mekkatorque",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8567,mapID=895,description="Alright, we got PLENTY of Azerite in this baby to blow up Mekkatorque and his airship. That radioactive freak is gonna pay for sendin' his toys to attack one of MY, er, OUR bases! Hop in, . We got a gnome to blow up.",starts={{npcID=145816,x=0.372,y=0.26,mapID=896}},ends={{npcID=146073,x=0.546,y=0.646,mapID=895}},coords={x=0.372,y=0.26,source="quest_giver",mapID=895},questType="standard"},
[54015] = {id=54015,name="In Deep",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10052,mapID=1355,description="I can keep this barrier up here for a time after our departure, but we cannot remain here. These soldiers will not be safe for long. We must go deeper into this place to seek a more defensible position.",starts={{npcID=150196,x=0.42,y=0.806,mapID=1355}},ends={{npcID=150196,x=0.42,y=0.806,mapID=1355}},coords={x=0.42,y=0.806,source="quest_giver",mapID=1355},questType="standard"},
[54018] = {id=54018,name="Descent",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=10052,mapID=1355,description="What has transpired! That is to say, what has transpired?! Yes, that is the appropriate response, is it not? I find our circumstances enthralling! Yet, tragic. I prattle on... Yes, Lor'themar asked me to send you to him at once. He is in need of your expertise, $p. I'll lower you down the falls safely. Good luck!",starts={{npcID=150206,x=0.366,y=0.868,mapID=1355}},ends={{npcID=150207,x=0.364,y=0.82,mapID=1355}},coords={x=0.366,y=0.868,source="quest_giver",mapID=1355},questType="standard"},
