[54629] = {id=54629,name="Paragon of the Proudmoore Admiralty",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8568,mapID=1161,description="The grateful leaders of the Proudmoore Admiralty have requested your presence. They wish to reward you for your continued aid to their house.",ends={{npcID=135808,x=0.676,y=0.218,mapID=1161}},questType="standard"},
[54632] = {id=54632,name="Paragon of the Zandalari Empire",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=9598,mapID=1165,description="The grateful leaders of the Zandalari Empire have requested your presence. They wish to reward you for your exceptional aid.",questType="standard"},
[54642] = {id=54642,name="G.E.A.R. Up",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=6457,mapID=27,description="That was a close one, but we managed to defeat Sparkspanner! Gnomanity and Azeroth are saved from a threat they didn't even know about. Hopefully, that's the last time we'll hear from any of Thermaplugg's old goons. We should return to Captain Sparknozzle. He will want a full report.",starts={{npcID=149503,x=0.394,y=0.268,mapID=120}},ends={{npcID=147943,x=0.418,y=0.314,mapID=27}},coords={x=0.394,y=0.268,source="quest_giver",mapID=27},questType="standard"},
[54709] = {id=54709,name="Candy Bucket",level=10,requiredLevel=10,faction="horde",expansion=7,zoneID=9598,mapID=1165,starts={{npcID=316754,x=0.5,y=0.815,mapID=1165}},ends={{npcID=316754,x=0.5,y=0.815,mapID=1165}},coords={x=0.5,y=0.815,source="quest_giver",mapID=1165},questType="standard"},
