[54755] = {id=54755,name="Not My Table",level=50,requiredLevel=50,faction="horde",expansion=7,questType="standard"},
[54941] = {id=54941,name="Scouting The Strand",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=10052,mapID=1355,description="It has been a long time since we have heard from our scouts at the outpost. They may have been cut off from us due to the naga attack. I need to check in with them and get an update on the movements of the naga forces. You should come with me, this will be a good opportunity for you to meet more of the clan and get a closer look at our operation.",questType="standard"},
[54943] = {id=54943,name="The Dark Ranger's Pupil",level=50,requiredLevel=50,faction="horde",expansion=7,zoneID=8317,description="Thank the abyss you're here, Huntmaster ! I'm concerned about Dark Ranger Velonara. We have become good friends during our time together in the Trueshot Lodge, and I fear she is in peril. She's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him. I have a bad feeling about all this. Could you check on her safety?",questType="standard"},
[54944] = {id=54944,name="The Dark Ranger's Pupil",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=8317,description="Thank the abyss you're here, fellow hunter! I'm concerned about Dark Ranger Velonara, who frequents the Trueshot Lodge. Velonara is a good friend, and I fear she is in peril. She's been training an apprentice dark ranger, a lad named Prelus. Newly raised, she said. At any rate, Prelus ran off after receiving a letter from his brother, and now Velonara has gone to Tirisfal Glades to find him. I have a bad feeling about all this. Would you be willing to check on her safety?",questType="standard"},
[54969] = {id=54969,name="Descent",level=50,requiredLevel=50,faction="alliance",expansion=7,zoneID=10052,mapID=1355,description="We've lost the bulk of our forces already; any more and we won't have enough to make a stand. This wreckage won't keep the naga at bay, so we must find safety elsewhere. You will have to trust me here, $p. Leap off the falls and you will descend safely.",starts={{npcID=150101,x=0.402,y=0.552,mapID=1355}},ends={{npcID=150101,x=0.402,y=0.552,mapID=1355}},coords={x=0.402,y=0.552,source="quest_giver",mapID=1355},questType="standard"},
[54986] = {id=54986,name="Vision of N'zoth Reward",level=50,requiredLevel=50,faction="none",expansion=7,questType="standard"},
[55012] = {id=55012,name="Cause for Concern",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,mapID=500,description="Shadowmaster O'Flannerty's behavior was unusual. His repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation. You should report back to Saralara Fizzlesprang .",questType="standard"},
[55023] = {id=55023,name="Bizmo's Brawlpub Awaits!",level=80,requiredLevel=80,faction="alliance",expansion=7,zoneID=2257,mapID=500,description="Tired of standing around in the boring old Trade District? Come on over to Bizmo's Brawlpub, and fight for the amusement of others! You might win, or you might get killed, but either way, you're going to have a great time. Grab an invitation and bring it to Han Heavypaw , near the front door. The Brawlpub awaits!",questType="standard"},
