[55099] = {id=55099,name="TBD NOT USED",level=10,requiredLevel=10,faction="none",expansion=7,zoneID=10290,mapID=1462,description="The fabled workbench of Rustbolt - MY workbench - has fallen into disrepair! This tragedy was no doubt caused by the same ruffians and miscreants who kidnapped me and Princess Wiggles. The VERY same ruffians and miscreants, in fact, who still show their faces in this very town on the regular. Their presence here is a veritable slap to our collective faces! Dispatch the snatchers quickly and recover my binder of blueprints. We may then commence crafting what we shall need to repair this.",questType="standard"},
