[55184] = {id=55184,name="Quilboar Shadow Magic",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=10424,mapID=1409,description="Quilboar are primitive and savage. They rarely practice any magic other than geomancy. But these particular quilboar seem to be dabbling in shadow magic. They must be stopped. Slay the quilboar in the den. They cannot spread this magic in the island!",starts={{npcID=154327,x=0.626,y=0.698,mapID=1409}},ends={{npcID=149915,x=0.562,y=0.59,mapID=1409}},coords={x=0.626,y=0.698,source="quest_giver",mapID=1409},questType="standard"},
[55224] = {id=55224,name="Rank 2 - Poen test",level=50,requiredLevel=50,faction="none",expansion=7,zoneID=10052,mapID=1355,description="Gather corrupted ink sacs from the Nazothian Brain squids. The naga use them to control us, let's see if it works the other way.",questType="standard"},
