[55498] = {id=55498,name="The Shimmering Crystal",level=1,requiredLevel=1,faction="alliance",expansion=7,zoneID=7332,description="Though the crystal appears familiar at first, upon contact with your finger it reveals itself as so much more. A grand, lost civilization appears in front of you. Fixtures of gold shimmer in every direction, bright feathers of purple occasionally falling from overhead. You hear the distant sounds of battle, culminating in a thunderous explosion that overwhelms all of your senses and turns your vision white. When your vision returns, you feel something within you pulling you toward Ashran .",ends={{npcID=151955,x=0.37,y=0.724,zoneID=7332}},questType="standard"},
